function movementCardMetaForUi(movement){const language=uiLanguage(),equipment=String(movement?.equipment||'').trim(),group=String(movement?.muscle_group||'').trim();const equipmentLabels=language==='en'?{'器械':'Machine','哑铃':'Dumbbell','杠铃':'Barbell','绳索':'Cable','自重':'Bodyweight'}:{Machine:'器械',Dumbbell:'哑铃',Barbell:'杠铃',Cable:'绳索',Bodyweight:'自重'};return equipment?(equipmentLabels[equipment]||equipment):language==='en'?groupLabelEnglish(group):groupLabel(group)}
function movementNamesForUi(movement){const canonical=String(movement?.display_name||movement?.movement_id||movement?.english_name||'');return{primary:canonical,secondary:movementCardMetaForUi(movement)}}
function movementPage(){const requestedId=state.routeParams?.movement_id||'';main.innerHTML=`<section class="page movement-index-page"><div class="movement-index-hero"><span class="eyebrow">05 / MOVEMENT ARCHIVE</span><h1>Movement<br>Index</h1><p>按训练部位浏览动作。使用频率更高的动作会自然靠前。</p><button class="movement-dictionary-entry material-control interactive-lift" data-view="dictionary"><span>CONTROLLED VOCABULARY</span><strong>Manage Dictionary</strong><b>→</b></button><div class="movement-toolbar"><input id="movement-search" class="control search" value="${esc(state.movementQuery||'')}" placeholder="Search movement, English name or alias…"><span class="result-count">${state.movements.length} movements</span></div></div><div id="movement-list" class="movement-groups"><div class="loading-page"><i></i><p>Reading movement index…</p></div></div></section>`;if(state.usageLoaded)renderMovementDirectory(state.movementQuery||'');loadMovementUsage();if(requestedId)loadMovementFocus(requestedId)}
async function loadMovementUsage(){if(state.usageLoaded){const usageStale=state.movements.some(m=>{const movementId=String(m.movement_id||'');return Number(state.movementUsage[movementId]?.count||0)!==Number(m.history_count||0)});if(!usageStale){renderMovementDirectory($('#movement-search')?.value||'');return}state.movementUsage={};state.usageLoaded=false;state.movementHistory=null}state.movementUsage=Object.fromEntries(state.movements.map(m=>{const movementId=String(m.movement_id||'');return [movementId,{count:Number(m.history_count||0),payload:null}]}));state.usageLoaded=true;renderMovementDirectory($('#movement-search')?.value||'')}
function invalidateMovementUsage(){state.movementUsage={};state.usageLoaded=false;state.movementHistory=null}
function renderMovementDirectory(q=''){const target=$('#movement-list');if(!target)return;const rows=state.movements.filter(m=>JSON.stringify(m).toLowerCase().includes((q||'').toLowerCase())).sort((a,b)=>(state.movementUsage[String(b.movement_id||'')]?.count||0)-(state.movementUsage[String(a.movement_id||'')]?.count||0));const groups=new Map();for(const m of rows){const key=m.muscle_group||'Other';if(!groups.has(key))groups.set(key,[]);groups.get(key).push(m)}const ordered=[...groups.entries()].sort((a,b)=>b[1].reduce((n,m)=>n+(state.movementUsage[String(m.movement_id||'')]?.count||0),0)-a[1].reduce((n,m)=>n+(state.movementUsage[String(m.movement_id||'')]?.count||0),0));const artFor=group=>{const key=String(group||'').toLowerCase();if(/shoulder|肩/.test(key))return'body-themes-v2/shoulders.png';if(/chest|胸/.test(key))return'body-themes-v2/chest.png';if(/back|pull|背/.test(key))return'body-themes-v2/back.png';if(/leg|glute|lower|腿|臀/.test(key))return'body-themes-v2/legs.png';if(/arms?|biceps|triceps|手臂|二头|三头/.test(key))return'body-themes-v2/arms.png';return'movement-art-core.png'};target.innerHTML=ordered.map(([group,items],groupIndex)=>`<section class="movement-group group-${groupIndex%3}"><header><span class="group-number">${String(groupIndex+1).padStart(2,'0')}</span><div><h2>${esc(uiLanguage()==='en'?groupLabelEnglish(group):groupLabel(group))}</h2><p>${esc(uiLanguage()==='en'?groupLabelEnglish(group):group)} · ${items.length} ${uiLanguage()==='en'?'movements':'个动作'}</p></div></header><div class="movement-mosaic">${items.map((m,i)=>{const names=movementNamesForUi(m,group),count=state.movementUsage[String(m.movement_id||'')]?.count||0,isLead=i===0&&count;return `<button class="movement-tile ${isLead?'tile-lead':count>=4?'tile-wide':'tile-slip'}" data-select-movement-id="${esc(m.movement_id)}">${isLead?`<img class="movement-art" src="assets/${artFor(group)}" alt="" aria-hidden="true">`:''}<span class="tile-count">${count} sessions</span><strong>${esc(names.primary)}</strong><small>${esc(names.secondary)}</small><em>Open trajectory →</em></button>`}).join('')}</div></section>`).join('')||'<p class="empty-note">No matching movements.</p>';const count=$('.result-count');if(count)count.textContent=`${rows.length} movements`}
async function loadMovementFocus(movementId){state.movementSelection=String(movementId||'');main.innerHTML=`<section class="page movement-detail-page"><button class="movement-back" data-movement-index>← Movement Index</button><div id="movement-focus"><div class="loading-page"><i></i><p>Loading recorded history…</p></div></div></section>`;const focus=$('#movement-focus');try{let payload=state.movementUsage[String(movementId)]?.payload;if(!payload)payload=await api(`/api/movement-history?movement_id=${encodeURIComponent(movementId)}&limit=50`);state.movementHistory=payload;if(!payload.movement){navigate('movements',{}, {replace:true,context:null});return}const movement=payload.movement||{},history=payload.history||[],names=movementNamesForUi(movement);focus.innerHTML=`<div class="movement-detail-hero"><span class="eyebrow">RECORDED TRAJECTORY</span><h1>${esc(names.primary)}</h1><p>${esc(names.secondary)}</p><div class="movement-meta"><span>${esc(groupLabel(movement.muscle_group))}</span><span>${history.length} recorded sessions</span></div></div><div class="trajectory"><div class="trajectory-line"></div>${history.map((r,i)=>`<article class="trajectory-entry ${i===0?'is-latest':''}"><div class="trajectory-marker">${String(i+1).padStart(2,'0')}</div><div class="history-date"><strong>${esc(r.date||'—')}</strong><small>Day ${esc(r.training_day??'—')} · Ex ${esc(r.order??'—')}</small></div><div class="history-content"><h3>${esc((r.sets_lines||[]).join(' · ')||'Recorded without structured sets')}</h3>${r.notes?`<p>${esc(r.notes)}</p>`:''}</div></article>`).join('')||'<div class="empty-copy"><h3>No history yet</h3><p>This movement exists in the dictionary but has no recorded sessions.</p></div>'}</div>`}catch{focus.innerHTML='<div class="empty-copy"><h3>History unavailable</h3><p>The local read-only service could not load this movement.</p></div>'}}

const issues=[['High','2026-06-29','训练记录','发现未识别动作','审核动作并映射或加入词典'],['Medium','2026-06-30','训练记录','检测到同日重复记录','检查并决定保留或合并'],['Medium','2026-06-25','身体数据','字段内容可能混入其他文字','打开记录并清理字段'],['Medium','2026-06-24','训练记录','动作组数未能结构化识别','核对并补充组数'],['Low','2026-06-20','饮食记录','缺少热量数据','补充当天热量']];
function checksPage(){main.innerHTML=`<section class="page page-grid"><div class="content">${pageHeader('Data Check','Unresolved issues, data hygiene, and structural consistency.')}<div class="toolbar"><button class="btn btn-primary">All Issues &nbsp; 5</button><button class="btn">High 2</button><button class="btn">Medium 3</button><button class="btn">Low 1</button></div><div class="table-wrap"><table><thead><tr><th>SEVERITY</th><th>DATE</th><th>AREA</th><th>ISSUE</th><th>SUGGESTED ACTION</th><th>OPEN</th></tr></thead><tbody>${issues.map((x,i)=>`<tr data-issue="${i}"><td><span class="severity ${x[0].toLowerCase()}">${x[0]}</span></td><td>${x[1]}</td><td>${x[2]}</td><td>${x[3]}</td><td>${x[4]}</td><td><button class="link">??</button></td></tr>`).join('')}</tbody></table></div>${pager()}</div><aside class="rail"><section class="rail-section" style="margin-top:0"><span class="eyebrow">NEW MOVEMENT APPROVAL</span><h2 style="font:400 24px var(--serif)">Movement detected</h2><p>Z-Press (Dumbbell)</p><button class="btn btn-primary" data-approval style="width:100%">Review decision</button></section><section class="rail-section"><span class="eyebrow">COMPONENT STATES</span><div class="state-stack" style="margin-top:16px"><div class="state">Empty · No matching issues</div><div class="state">Loading · Scanning data</div><div class="state success">Success · All good</div><div class="state warning">Warning · Needs attention</div><div class="state error">Error · Scan interrupted</div></div></section><p style="color:#666;font-size:11px">UI preview only. The stable desktop checker remains authoritative.</p></aside></section>`}

function reviewPage(raw){main.innerHTML=`<section class="page review"><div class="review-top">${pageHeader('Unavailable','Review extracted data before saving to your local journal.')}<button class="btn" data-back>Back to edit</button></div><div class="summary-strip">${[['Date','2026-07-01'],['Weight','67.8 kg'],['Calories','1570 kcal'],['Training','胸部, 肩部'],['Movements','6 · New 1']].map(x=>`<div class="metric"><label>${x[0]}</label><strong>${x[1]}</strong></div>`).join('')}</div>${['BODY 身体','DIET 饮食','TRAINING 训练','MOVEMENTS 动作识别','WARNINGS 警告'].map((t,i)=>`<section class="review-section"><h3>${t}</h3><p>${i===4?'Duplicate date · New movement · Unrecognized sets':i===3?'1. 卧推 · 4 sets &nbsp; 2. 引体向上 · 3 sets &nbsp; 3. 绳索面拉 · 3 sets':esc(short(raw||'Preview data from the current draft.',180))}</p></section>`).join('')}<div class="bottom-bar"><button class="btn" data-back>Cancel</button><button class="btn" data-back>← Back to edit</button><button class="btn btn-primary" data-duplicate>Confirm & Save</button></div></section>`}

 function modal(title,content,options={}){const legacyActions=typeof options==='string'?options:'';const config=options&&typeof options==='object'?options:{};const light=Boolean(config.light);const actions=legacyActions||config.actions||'';root.innerHTML=`<div class="overlay"><section class="modal ${light?'light':''}"><button class="close" data-close>×</button><h2>${esc(title)}</h2>${content}${actions?`<div class="modal-actions">${actions}</div>`:''}</section></div>`;localizeSharedSurface()}
async function loadPhoneInboxClient(){if(!phoneInboxClientPromise)phoneInboxClientPromise=import(`./phone-inbox-client.js?v=20260904-03`);return phoneInboxClientPromise}
function phoneInboxDate(value){const date=new Date(Number(value)||value);return Number.isNaN(date.getTime())?String(value||''):date.toLocaleString(uiLanguage()==='en'?'en-US':'zh-CN',{hour12:false})}
function phoneInboxError(error){const english=uiLanguage()==='en';if(error?.code==='PHONE_INBOX_ACCOUNT_REQUIRED')return english?'This session is anonymous or temporary and cannot access an account inbox. Sign in with the same CloudBase account used on your phone.':'当前只是匿名或临时登录，无法归入账号收件箱。请登录与手机端相同的 CloudBase 账号。';if(error?.code==='PHONE_INBOX_AUTH_REQUIRED'||String(error?.message||'').includes('AUTH_REQUIRED'))return english?'Sign in to your CloudBase account to read phone submissions.':'请先登录 CloudBase 账号，才能读取手机发送的内容。';if(String(error?.code||'').includes('PHONE_INBOX_')&&String(error?.code||'').includes('TIMEOUT'))return english?'The request timed out after 15 seconds. Check your connection and try again.':'读取等待超过 15 秒，未显示为成功。请检查网络后重试。';return english?'Phone submissions are temporarily unavailable. Try again later.':error?.message||'手机发送记录暂时无法读取，请稍后重试。'}
function phoneInboxDiagnostic(error){return String(error?.code||'PHONE_INBOX_SYNC_FAILED').replace(/[^A-Z0-9_.-]/gi,'_').slice(0,80)}
function phoneInboxSyncNotice(error){const code=phoneInboxDiagnostic(error);return uiLanguage()==='en'?`Cloud sync failed (${code}). It will retry automatically.`:`云端同步失败（${code}），将自动重试。`}
function phoneInboxNeedsAccount(error){return ['PHONE_INBOX_AUTH_REQUIRED','PHONE_INBOX_ACCOUNT_REQUIRED'].includes(error?.code)}
function renderPhoneInboxModal(){
  const english=uiLanguage()==='en';
  const inbox=state.phoneInbox;
  if(inbox.status==='loading'){modal('当日训练记录','<div class="loading-page" style="height:170px"><i></i><p>正在读取最近发送内容…</p></div>');return}
  if(inbox.status==='error'){modal('当日训练记录',`<p class="dm-form-error">${esc(inbox.error||'手机发送记录暂时无法读取。')}</p>`,`<button class="btn" data-phone-inbox-refresh>重试</button><button class="btn btn-primary" data-close>关闭</button>`);return}
  if(inbox.status==='auth'){modal('当日训练记录',`<p class="phone-inbox-copy">手机内容会先保存在你的私有 CloudBase 收件集合中。登录只用于读取和处理这些内容，不会直接写入正式记录。</p><form class="phone-inbox-login" data-phone-inbox-login><label><span>CloudBase 账号</span><input name="username" autocomplete="username" required></label><label><span>密码</span><input name="password" type="password" autocomplete="current-password" required></label><p class="dm-form-error">${esc(inbox.error||"请登录后继续。")}</p><button class="btn btn-primary" type="submit" ${inbox.busy?'disabled':''}>${inbox.busy?'登录中…':'登录并读取'}</button></form>`);return}
  const items=inbox.items||[];
  const list=items.length?items.map(item=>`<article class="phone-inbox-item"><header><strong>${esc(item.title||'手机训练记录')}</strong><time>${esc(phoneInboxDate(item.received_at))}</time></header><pre>${esc(item.text||'')}</pre><div class="phone-inbox-item-actions"><button class="btn btn-primary" data-phone-inbox-use="${esc(item._id)}">放入 Daily Entry</button><button class="btn" data-phone-inbox-copy="${esc(item._id)}">复制内容</button><button class="btn btn-light" data-phone-inbox-processed="${esc(item._id)}">标记已处理</button><button class="btn btn-danger" data-phone-inbox-delete="${esc(item._id)}">删除</button></div></article>`).join(''):'<p class="phone-inbox-empty">目前没有手机发送的内容。</p>';
  const sourceNote=english?(inbox.cached?'Last 7 stored locally · cloud unavailable; sync will retry.':'Last 7 stored locally (updated from cloud).'):(inbox.cached?'本地最近 7 次 · 云端暂不可用，稍后会自动重试同步':'本地最近 7 次（云端读取后更新）');
  const storedCount=english?`${items.length} stored locally · ${sourceNote}`:`本地保留 ${items.length} 次发送 · ${sourceNote}`;
  const notice=inbox.notice||(inbox.syncErrorCode?phoneInboxSyncNotice({code:inbox.syncErrorCode}):'');
  modal('当日训练记录',`<div class="phone-inbox-head"><p>手机发来的内容会先出现在这里。可以复制原文，或选择“放入 Daily Entry”继续识别、预览和确认保存。</p><span>${storedCount}</span></div><div class="phone-inbox-list">${list}</div>${notice?`<p class="phone-inbox-notice" role="status">${esc(notice)}</p>`:''}`,`<button class="btn" data-phone-inbox-refresh>${inbox.busy?(english?'Loading…':'读取中…'):(english?'Refresh':'刷新')}</button><button class="btn btn-primary" data-close>${english?'Close':'关闭'}</button>`);
}
async function phoneInboxCachedItems(error){
  if(Array.isArray(error?.localItems))return error.localItems;
  try{return state.phoneInboxClient?.localItems?await state.phoneInboxClient.localItems():[]}catch{return []}
}
// 后台静默同步：启动和定时刷新时读取云端并更新本地最近 7 次；云端不可用时保留本地文件快照。
async function syncPhoneInboxBackground(){
  try{
    const client=await loadPhoneInboxClient();state.phoneInboxClient=client;
    state.phoneInbox.items=await client.listRecent();
    state.phoneInbox.status='ready';state.phoneInbox.cached=false;state.phoneInbox.error='';state.phoneInbox.notice='';state.phoneInbox.syncErrorCode='';
  }catch(error){
    const cached=await phoneInboxCachedItems(error);
    if(phoneInboxNeedsAccount(error)){state.phoneInbox.status='auth';state.phoneInbox.error=phoneInboxError(error);state.phoneInbox.syncErrorCode=''}
    else if(cached.length){state.phoneInbox.items=cached;state.phoneInbox.status='ready';state.phoneInbox.cached=true;state.phoneInbox.notice='';state.phoneInbox.syncErrorCode=phoneInboxDiagnostic(error)}
    else if(state.phoneInbox.status!=='ready'){state.phoneInbox.status='closed';state.phoneInbox.syncErrorCode=''}
  }
  if(document.querySelector('#overlay-root .phone-inbox-list'))renderPhoneInboxModal();
}
async function openPhoneDailyRecords(){
  if(state.phoneInbox.status==='ready'&&(state.phoneInbox.items||[]).length){renderPhoneInboxModal();syncPhoneInboxBackground();return}
  state.phoneInbox={status:'loading',items:[],error:'',notice:'',syncErrorCode:'',busy:false,cached:false};renderPhoneInboxModal();
  try{const client=await loadPhoneInboxClient();state.phoneInboxClient=client;state.phoneInbox.items=await client.listRecent();state.phoneInbox.status='ready';state.phoneInbox.cached=false;state.phoneInbox.notice='';state.phoneInbox.syncErrorCode=''}catch(error){
    const cached=await phoneInboxCachedItems(error);
    if(phoneInboxNeedsAccount(error)){state.phoneInbox.status='auth';state.phoneInbox.error=phoneInboxError(error)}
    else if(cached.length){state.phoneInbox.items=cached;state.phoneInbox.status='ready';state.phoneInbox.cached=true;state.phoneInbox.syncErrorCode=phoneInboxDiagnostic(error)}
    else{state.phoneInbox.status=['PHONE_INBOX_AUTH_REQUIRED','PHONE_INBOX_ACCOUNT_REQUIRED'].includes(error?.code)?'auth':'error';state.phoneInbox.error=phoneInboxError(error)}
  }
  if(state.phoneInbox.status==='error')modal('当日训练记录',`<p class="dm-form-error">${esc(state.phoneInbox.error)}</p>`,`<button class="btn" data-phone-inbox-refresh>重试</button><button class="btn btn-primary" data-close>关闭</button>`);else renderPhoneInboxModal();
}
async function signInPhoneInbox(form){
  state.phoneInbox.busy=true;renderPhoneInboxModal();
  try{const client=await loadPhoneInboxClient();state.phoneInboxClient=client;state.phoneInbox.items=await client.signIn(form.elements.username.value,form.elements.password.value);state.phoneInbox.status='ready';state.phoneInbox.error=''}catch(error){state.phoneInbox.status='auth';state.phoneInbox.error=phoneInboxError(error)}
  state.phoneInbox.busy=false;renderPhoneInboxModal();
}
async function refreshPhoneDailyRecords(){if(!state.phoneInboxClient)return openPhoneDailyRecords();state.phoneInbox.status='loading';state.phoneInbox.busy=true;renderPhoneInboxModal();try{state.phoneInbox.items=await state.phoneInboxClient.listRecent();state.phoneInbox.status='ready';state.phoneInbox.cached=false;state.phoneInbox.error='';state.phoneInbox.notice='';state.phoneInbox.syncErrorCode=''}catch(error){const cached=await phoneInboxCachedItems(error);if(phoneInboxNeedsAccount(error)){state.phoneInbox.status='auth';state.phoneInbox.error=phoneInboxError(error);state.phoneInbox.syncErrorCode=''}else if(cached.length){state.phoneInbox.items=cached;state.phoneInbox.status='ready';state.phoneInbox.cached=true;state.phoneInbox.error='';state.phoneInbox.notice='';state.phoneInbox.syncErrorCode=phoneInboxDiagnostic(error)}else{state.phoneInbox.status='error';state.phoneInbox.error=phoneInboxError(error);state.phoneInbox.syncErrorCode=''}}state.phoneInbox.busy=false;renderPhoneInboxModal()}
function usePhoneInboxItem(id){const item=state.phoneInbox.items.find(row=>row._id===id);if(!item)return;state.phoneInboxDraft=String(item.text||'');root.innerHTML='';navigate('quick');window.setTimeout(()=>{const input=$('#raw-entry');if(input){input.value=state.phoneInboxDraft;input.focus();showToast('已放入 Daily Entry，请先识别和预览。')}state.phoneInboxDraft=''},0)}
async function copyPhoneInboxItem(id){const item=state.phoneInbox.items.find(row=>row._id===id);const text=String(item?.text||'').trim();if(!text)return;try{if(!navigator.clipboard?.writeText)throw new Error('clipboard unavailable');await navigator.clipboard.writeText(text);state.phoneInbox.notice='已复制这条手机记录，可直接粘贴到任意输入框。';showToast('手机记录已复制。')}catch(error){state.phoneInbox.notice='当前环境无法访问剪贴板，请使用“放入 Daily Entry”。';showToast('当前环境无法访问剪贴板。')}renderPhoneInboxModal()}
async function markPhoneInboxProcessed(id){if(!state.phoneInboxClient)return;state.phoneInbox.busy=true;renderPhoneInboxModal();try{state.phoneInbox.items=await state.phoneInboxClient.updateStatus(id,'processed');state.phoneInbox.notice='已标记为已处理，原文仍保留在最近记录中。';state.phoneInbox.error=''}catch(error){state.phoneInbox.error=phoneInboxError(error)}state.phoneInbox.busy=false;renderPhoneInboxModal()}
function confirmPhoneInboxDelete(id){const item=state.phoneInbox.items.find(row=>row._id===id);if(!item)return;modal('删除手机记录',`<p class="phone-inbox-copy">确定删除这条记录吗？这会按当前明确的删除操作移除云端原文及本地快照，且无法恢复；自动保留 7 条不会删除云端内容。</p><div class="phone-inbox-item"><pre>${esc(short(String(item.text||''),400))}</pre></div>`,`<button class="btn" data-close>取消</button><button class="btn btn-danger" data-phone-inbox-delete-confirm="${esc(id)}">确认删除</button>`)}
async function deletePhoneInboxItem(id){if(!state.phoneInboxClient)return;state.phoneInbox.busy=true;renderPhoneInboxModal();try{state.phoneInbox.items=await state.phoneInboxClient.removeItem(id);state.phoneInbox.notice='已删除该记录。';state.phoneInbox.error=''}catch(error){state.phoneInbox.error=phoneInboxError(error)}state.phoneInbox.busy=false;renderPhoneInboxModal()}
 let dataModuleLlmTemplate=null;
 let dataModuleLlmPrompt="";
 function englishModuleCatalog(template){return (template?.modules||[]).map(item=>`- ${item.label||item.module_id} | aliases=${(item.aliases||[]).join(', ')} | type=${item.data_type||'text'} | example=${item.label||item.module_id}: <value> | category=${item.category_label||item.category_id||'Body'} | analysis=${item.capabilities?.analysis_visible?'on':'off'} | statistics=${item.capabilities?.statistics_visible?'on':'off'} | rule=${item.value_rule||'preserve the explicit source text'}`).join('\n')||'- No active custom record fields are currently registered.'}
 function buildEnglishDataModulePrompt(template){const native=(template?.native_fields||[]).map(item=>`- ${item.field||item.key} | aliases=${(item.aliases||[]).join(', ')} | example=${item.line_example||''}`).join('\n');return `You are the Fitness Ledger Daily Entry formatter.
Turn the user's natural-language notes for one day into plain text that can be pasted into Daily Entry. Format, classify, and estimate only where the rules allow; do not write a report, analysis, or explanation. This template describes the current registry and general product rules only. It contains no personal history, long-term memory, or fixed eating habits.

[Canonical structure example]
date: YYYY-MM-DD
weight: <number> kg
Energy: <text>
Bowel movement: <text>
Cardio: <text>

calories: <number>
protein: <number>
carbs: <number>
fat: <number>

diet:
<food and amounts>

diet notes:
<estimation basis or diet notes>

training: <training area>
 1. <movement name>
 <weight>-<reps>-<sets>
 notes: <movement note>

training notes: <notes for the whole session>

cardio:
<explicit cardio content or none>

notes:
<whole-day notes>

[Training indentation]
The top-level training: label must start at column 1. Every non-empty movement-related line inside the training block must start with exactly one ASCII space, including superset lines, movement numbers, ordinary sets, complex sets, sets: lines, and movement notes. Never use tabs or extra leading spaces. training notes: is top-level and starts at column 1. Keep one blank line between movements.

[Ordinary sets, complex sets, and supersets]
An ordinary set is weight-reps-sets. Do not merge adjacent loads into a complex set unless the user explicitly describes continuous, drop-set, mechanical-drop, or multi-segment execution within one set. A complex set is one movement and one set with multiple continuous segments. Use ASCII-only syntax: (7.5+5)-(6+8)-3 or explicit sets: rows when structures differ. A superset is a clearly stated relationship between two or more different movements in one session; it is not a complex set. Only output one indented line such as superset: A = movement 1, movement 2 when the user explicitly states that relationship. Keep the movements separate.

[Notes scope]
Keep movement notes under the movement, training notes for the whole session, diet notes for diet parameters or estimates, and top-level notes for the whole day. Preserve the user's wording, tone, and numbers. Do not move notes between scopes.

[Dates, cardio, nutrition, and corrections]
Resolve today/yesterday or midnight only with reliable current date/time context; otherwise require YYYY-MM-DD. Preserve only explicitly recorded cardio; explicit no-cardio becomes none, and omitted cardio stays omitted. Prefer package nutrition values, net weights, and explicit parameters. Put uncertainty in diet notes and do not invent precision. Correction language overwrites the previous value; add language appends. Always output the complete current Daily Entry, never a diff. If a previous complete version is not present in the conversation, ask for the complete current state.

[Output rules]
1. Output exactly one complete plain-text Daily Entry. No Markdown fences, JSON, tables, preface, or closing explanation.
2. Keep top-level labels flush-left and use the order date, weight, optional body fields, registered Body fields, bowel movement, nutrition, registered Diet fields, diet, training, registered Training fields, and cardio.
3. Preserve explicit movements, sets, food, machine data, subjective feelings, and notes. Do not delete, paraphrase, merge, or infer missing sleep, fatigue, pain, status, training quality, or cardio.
4. Use only registered custom fields. Preserve text fields as text and numeric fields as explicit numbers. Do not expose internal module IDs or move registered fields into notes.

[Currently registered custom fields]
${englishModuleCatalog(template)}

[Current standard field catalog]
${native}

[Execution]
Format the following raw record and output only the resulting Daily Entry:
{{daily_text}}`}
