function rawDisclosure(label,raw){if(!raw||raw==='—')return'';const text=typeof raw==='string'?raw:(raw.raw_text||raw.text||raw.raw||'');return text?`<details class="raw-disclosure"><summary>${esc(label)}</summary><pre>${esc(text)}</pre></details>`:''}
function setsHtml(movement){const sets=movement.sets||movement.structured_sets||[];if(Array.isArray(sets)&&sets.length)return `<div class="structured-sets">${sets.map((set,index)=>`<div><span>${index+1}</span><b>${esc(readable(set,'weight_text','weight','load','load_text'))}</b><em>${esc(readable(set,'reps'))} 次</em><em>${esc(readable(set,'sets','set_count'))} 组</em></div>`).join('')}</div>`;const summary=readable(movement,'sets_summary','sets_text','raw_detail','detail');return summary!=='—'?`<p class="structured-summary">${esc(summary)}</p>`:'<p class="structured-empty">暂无结构化组数</p>'}
function trainingHtml(sessions=[]){return sessions.map((session,sessionIndex)=>{const movements=session.movements||session.exercises||[];return `<article class="structured-session"><header><div><span>训练 ${sessionIndex+1}</span><h3>${esc(readable(session,'split','Split','training'))}</h3></div><small>${esc(readable(session,'day_number','training_day','date','Date'))}</small></header>${movements.length?`<div class="structured-movements">${movements.map((movement,index)=>`<section><div class="structured-movement-head"><span>${String(index+1).padStart(2,'0')}</span><h4>${esc(readable(movement,'display_name','movement_name','name','movement'))}</h4>${movement.standardized===false?'<small>未标准化</small>':''}</div>${setsHtml(movement)}${readable(movement,'notes','note')!=='—'?`<p class="structured-note">${esc(readable(movement,'notes','note'))}</p>`:''}${rawDisclosure('查看动作原始写法',readable(movement,'raw','raw_detail'))}</section>`).join('')}</div>`:`<p class="structured-summary">${esc(readable(session,'Standardized Summary','standardized_summary','movement_summary'))}</p>`}${readable(session,'notes','Notes')!=='—'?`<p class="structured-note"><b>训练备注</b>${esc(readable(session,'notes','Notes'))}</p>`:''}${rawDisclosure('查看训练原始记录',readable(session,'raw_record','Raw Record','raw'))}${session.training_session_id?`<button class="btn" data-raw-edit-session="${esc(session.training_session_id)}">编辑训练原文（先看差异）</button>`:''}</article>`}).join('')||'<p class="structured-empty">当日没有训练记录</p>'}
function structuredRecordHtml(record){const body=record.body||{},diet=record.diet||{},sessions=Array.isArray(record.training)?record.training:record.training?[record.training]:[],rawEntries=record.raw_entries||[],modules=record.data_modules||[];return `<div class="structured-record"><section class="structured-section is-summary"><span class="eyebrow">记录摘要</span>${detailFacts([['日期',record.date||'—'],['训练主题',readable(sessions[0],'split','Split','training')],['体重',readable(body,'Weight (kg)','weight'),'kg'],['热量',readable(diet,'Calories (kcal)','calories'),'kcal']])}</section><section class="structured-section"><h3>身体记录</h3>${detailFacts([['体重',readable(body,'Weight (kg)','weight')]])}${readable(body,'Notes','notes')!=='—'?`<p class="structured-note">${esc(readable(body,'Notes','notes'))}</p>`:''}</section><section class="structured-section"><h3>饮食记录</h3>${detailFacts([['热量',readable(diet,'Calories (kcal)','calories'),'kcal'],['蛋白质',readable(diet,'Protein (g)','protein'),'g'],['碳水',readable(diet,'Carbs (g)','carbs'),'g'],['脂肪',readable(diet,'Fat (g)','fat'),'g']])}${readable(diet,'Food Summary','food_summary')!=='—'?`<div class="structured-copy"><b>饮食摘要</b><p>${esc(readable(diet,'Food Summary','food_summary'))}</p></div>`:''}${readable(diet,'Notes','notes')!=='—'?`<p class="structured-note">${esc(readable(diet,'Notes','notes'))}</p>`:''}</section><section class="structured-section"><h3>训练记录</h3>${trainingHtml(sessions)}</section><section class="structured-section"><h3>数据模块</h3>${modules.length?modules.map((item,index)=>`<div class="detail-row"><label>${esc(item.module_id||'module')}</label><div>${esc(item.value)} ${esc(item.actual_unit||'')} <button class="btn" data-module-edit="${index}">编辑</button></div>`).join(''):'<p class="structured-empty">暂无数据</p>'}</section>${rawEntries.map((entry,index)=>rawDisclosure(`查看原始输入 ${index+1}`,entry)).join('')}</div>`}
async function recordDetail(date){modal(date,'<div class="loading-page" style="height:240px"><i></i></div>');try{const record=await api(`/api/record?date=${encodeURIComponent(date)}`),panel=$('.modal');state.currentRecordDetail=record;panel.classList.add('structured-detail-modal');panel.innerHTML=`<button class="close" data-close>×</button><span class="eyebrow">DAILY RECORD / STRUCTURED</span><h2>${esc(date)}</h2><div class="modal-actions"><button class="btn btn-primary" data-record-edit>编辑全部记录</button></div>${structuredRecordHtml(record)}`}catch{showToast('无法读取该日记录详情。')}}
function editModuleRecord(index){const record=state.currentRecordDetail?.data_modules?.[Number(index)];if(!record)return;modal('编辑数据模块',`<form id="module-record-form" class="record-edit-form" data-record-id="${esc(record.record_id)}" data-revision="${esc(record.revision||1)}"><label><span>${esc(record.module_id||'值')}</span><input name="value" value="${esc(record.value??'')}"></label></form>`,{actions:'<button class="btn" data-close>取消</button><button class="btn btn-primary" data-module-save>保存修改</button>'})}
async function saveModuleRecord(){const form=$('#module-record-form');if(!form)return;const value=form.elements.value.value,button=$('[data-module-save]');button.disabled=true;try{await postApi('/api/data-module-record/update',{record_id:form.dataset.recordId,expected_revision:Number(form.dataset.revision||1),values:{value}});root.innerHTML='';await refreshWebState();showToast('数据模块已保存并重新读取。')}catch(error){button.disabled=false;showToast(error.message||'数据模块保存失败。')}}
function openRawTrainingEditor(sessionId){const session=state.currentRecordDetail?.training?.find(item=>String(item.training_session_id)===String(sessionId));if(!session)return;modal('编辑训练原文',`<form id="raw-training-form" class="record-edit-form" data-session-id="${esc(sessionId)}" data-revision="${esc(session.revision||1)}"><label class="is-wide"><span>新的原始输入</span><textarea name="raw_text" rows="8">${esc(session.raw_record||'')}</textarea></label><p class="record-edit-note">点击预览后会列出动作新增、删除、映射、组数和备注变化；未确认前不会写入。</p></form>`,{actions:'<button class="btn" data-close>取消</button><button class="btn btn-primary" data-raw-preview>生成差异</button>'})}
async function previewRawTraining(){const form=$('#raw-training-form');if(!form)return;const button=$('[data-raw-preview]');button.disabled=true;try{const preview=await postApi('/api/training/raw-preview',{training_session_id:form.dataset.sessionId,expected_revision:Number(form.dataset.revision||1),raw_text:form.elements.raw_text.value});const diff=preview.diff||{};modal('训练原文差异确认',`<p>以下变更将统一更新原文修订、训练会话、动作历史和摘要。</p><div class="detail-list"><div class="detail-row"><label>新增动作</label><div>${esc(JSON.stringify(diff.added||[]))}</div></div><div class="detail-row"><label>删除动作</label><div>${esc(JSON.stringify(diff.removed||[]))}</div></div><div class="detail-row"><label>变化动作</label><div>${esc(JSON.stringify(diff.updated||[]))}</div></div><div class="detail-row"><label>未映射</label><div>${esc(JSON.stringify(diff.unmapped||[]))}</div></div></div>`,{actions:`<button class="btn" data-close>取消</button><button class="btn btn-primary" data-raw-confirm="${esc(preview.preview_id)}">确认并保存</button>`})}catch(error){button.disabled=false;showToast(error.message||'训练原文差异生成失败。')}}
async function confirmRawTraining(previewId){const button=$('[data-raw-confirm]');if(button)button.disabled=true;try{await postApi('/api/training/raw-apply',{preview_id:previewId,confirmed:true});root.innerHTML='';await refreshWebState();showToast('训练原文及其结构化结果已统一更新。')}catch(error){if(button)button.disabled=false;showToast(error.message||'训练原文保存失败。')}}
function editDayRecord(value){const [kind,entryDate]=String(value||'').split('|');const rows={body:state.body,diet:state.diet,training:state.training}[kind]||[];const index=rows.findIndex(row=>dateOf(row)===entryDate);if(index>=0)realRecordDetail(kind,index);else showToast('该日暂无可编辑的正式记录。')}
async function movementDetail(movementId){modal(movementId,'<div class="loading-page" style="height:240px"><i></i></div>');try{const h=await api(`/api/movement-history?movement_id=${encodeURIComponent(movementId)}&limit=8`);$('.modal').innerHTML=`<button class="close" data-close>×</button><span class="eyebrow">MOVEMENT HISTORY</span><h2>${esc(h.movement?.display_name||movementId)}</h2><div class="detail-list">${(h.history||h.records||h||[]).map(r=>`<div class="detail-row"><label>${esc(dateOf(r))}</label><div>${esc(short(value(r,'sets_summary','raw_detail','detail'),220))}</div></div>`).join('')||'<p>No structured history found.</p>'}<div class="modal-actions"><button class="btn" data-drawer="movement">Open editor preview</button><button class="btn btn-primary" data-close>Close</button></div>`}catch{showToast('Unable to load movement history.')}}
function drawer(type){const light=type==='movement';root.innerHTML=`<div class="overlay" data-close></div><aside class="drawer ${light?'light':''}"><button class="close" data-close>×</button><span class="eyebrow" style="${light?'color:#676962':''}">${type==='movement'?'MOVEMENT EDITOR':'RECORD EDITOR · UI PREVIEW'}</span><h2 style="font:400 30px var(--serif)">${type==='movement'?'Movement record':'Edit Body Record'}</h2>${['Date','Name / Training','Weight or Sets','Details','Notes'].map((f,i)=>`<label class="field"><span>${f}</span>${i===4?'<textarea rows="5">Preview only</textarea>':`<input value="${i===0?'2026-07-01':''}">`}</label>`).join('')}<button class="btn btn-primary" style="width:100%" data-mock="Write actions are intentionally disabled in Web preview.">Save changes</button></aside>`}
function duplicate(){modal('Duplicate Date Detected',`<p>2026-07-01 的记录已存在。请选择如何处理此记录：</p><div class="detail-list"><button class="btn btn-primary" data-mock="Overwrite is disabled in read-only preview.">Overwrite daily records →</button><button class="btn btn-light" data-mock="Adding a session is disabled in read-only preview.">Add as second training session →</button><button class="btn btn-light" data-close>Cancel</button></div>`,{light:true})}
function approval(){modal('New movement approval',`<p>This movement is not in your dictionary.</p><div class="detail-row"><label>Detected</label><strong>Z-Press (Dumbbell)</strong></div><div class="detail-list"><label class="record"><input type="radio" name="a" checked> Add to dictionary</label><label class="record"><input type="radio" name="a"> Map to existing movement</label><label class="record"><input type="radio" name="a"> Keep raw only</label></div>`,{actions:`<button class="btn" data-close>Cancel</button><button class="btn btn-primary" data-mock="Approval is a UI preview only.">Save decision</button>`})}

/* Visual-only archive overrides. These keep the same data/API contracts while repairing dense Chinese layout. */
bodyPage=function(){main.innerHTML=`<section class="page archive-page body-archive"><div class="archive-heading">${pageHeader('Body Records','Daily measurements as personal body slips, with notes kept readable.')}</div><div class="toolbar body-toolbar"><input class="control search" id="body-search" placeholder="Search notes..."><select class="control"><option>All time</option></select><select class="control"><option>Training</option></select></div><div id="body-rows" class="body-ledger"></div>${pager()}</section>`;renderBodyRows()}
renderBodyRows=function(q=''){const rows=state.body.filter(r=>JSON.stringify(r).toLowerCase().includes(q.toLowerCase()));$('#body-rows').innerHTML=rows.map((r,i)=>`<article class="body-slip ${i===0?'is-featured':''}" data-detail="body" data-index="${state.body.indexOf(r)}"><div class="body-slip-date"><span>${String(i+1).padStart(2,'0')}</span><strong>${esc(dateOf(r))}</strong></div><div class="body-slip-weight"><b>${esc(value(r,'Weight (kg)'))}</b><small>kg</small></div><div class="body-slip-meta"><span>训练 <strong>${esc(short(value(r,'Training'),24))}</strong></span></div><p>${esc(short(value(r,'Notes'),160))}</p><button class="record-open">Open record →</button></article>`).join('')}
dietPage=function(){main.innerHTML=`<section class="page archive-page diet-archive"><div class="archive-heading">${pageHeader('Diet Records','Meals, macros, and context arranged as daily editorial slips.')}</div><div class="toolbar diet-toolbar"><input class="control" value="Recent records" readonly><select class="control"><option>All Meals</option></select><input class="control search" id="diet-search" placeholder="Search notes or food..."></div><div id="diet-rows" class="diet-slips"></div>${pager()}</section>`;renderDietRows()}
renderDietRows=function(q=''){const rows=state.diet.filter(r=>JSON.stringify(r).toLowerCase().includes(q.toLowerCase()));$('#diet-rows').innerHTML=rows.map((r,i)=>`<article class="diet-slip ${i%4===1?'slip-offset':''}" data-detail="diet" data-index="${state.diet.indexOf(r)}"><span class="slip-index">${String(i+1).padStart(2,'0')}</span><h3>${esc(dateOf(r))}</h3><div class="macro-line"><strong>${esc(value(r,'Calories (kcal)'))}<small>kcal</small></strong><span>P ${esc(value(r,'Protein (g)'))}</span><span>C ${esc(value(r,'Carbs (g)'))}</span><span>F ${esc(value(r,'Fat (g)'))}</span></div><p>${esc(short(value(r,'Food Summary'),120))}</p><small>${esc(short(value(r,'Notes'),78))}</small><button class="record-open">Read detail →</button></article>`).join('')}
/* Secondary-page refinement overrides. Data contracts remain unchanged. */
quickPage=function(){const t=state.today,b=t.body||{},d=t.diet||{},tr=t.training||{};main.innerHTML=`<section class="page entry-page"><header class="entry-header"><div><span class="eyebrow">02 / Unavailable</span><h1 class="page-title">Unavailable</h1><p class="page-subtitle">Unavailable</p></div><button class="home-text-link" data-go="home">Unavailable</button></header><div class="entry-spread"><article class="capture"><span class="eyebrow">Unavailable ? Unavailable</span><h2>Unavailable</h2><textarea id="raw-entry" placeholder="Unavailable"></textarea><div class="actions"><button class="btn btn-primary" id="parse">Unavailable</button><button class="btn btn-light" data-mock="Unavailable">Undo last save</button></div><p class="phase">Read-only Web preview. Formal writes remain in the stable desktop app.</p></article><aside class="entry-digest"><div class="entry-digest-head"><span class="eyebrow">?? / ${esc(t.date||'Unavailable')}</span><strong>${esc(value(b,'Weight (kg)'))}<small> kg</small></strong></div><div class="entry-digest-grid"><span><b>${esc(value(d,'Calories (kcal)'))}</b> kcal</span><span><b>${esc(value(tr,'split','Split'))}</b> split</span></div><div class="digest-recent"><span class="eyebrow">Unavailable</span>${state.recent.slice(0,3).map((r,i)=>`<div class="digest-record"><span>0${i+1}</span><strong>${esc(r.date)}</strong><small>${esc(r.weight||'-')} kg / ${esc(r.calories||'-')} kcal</small><button data-record="${esc(r.date)}">??</button></div>`).join('')}</div></aside></div></section>`}

bodyPage=function(){main.innerHTML=`<section class="page archive-page body-archive"><div class="body-folio">BODY / LOCAL ARCHIVE / PRIVATE</div><div class="archive-heading">${pageHeader('Body Records','Daily measurements as personal body slips, with notes kept readable.')}</div><div class="body-controls-row"><div class="toolbar body-toolbar"><input class="control search" id="body-search" placeholder="Search notes or date..."><select class="control" id="body-time"><option value="0">All time</option><option value="7">Recent 7 days</option><option value="14">Recent 14 days</option><option value="30">Recent 30 days</option></select><select class="control" id="body-order"><option value="recent">Newest first</option><option value="oldest">Oldest first</option></select></div><div id="body-weight-slot" class="body-weight-slot"></div></div><div id="body-rows" class="body-ledger"></div>${pager()}</section>`;renderBodyRows()}
renderBodyRows=function(q=$('#body-search')?.value||''){const days=Number(selectedValue('body-time')||0);let rows=state.body.filter(r=>fuzzyMatch(r,q)).filter(r=>withinDays(r,days,state.body));if(selectedValue('body-order')==='oldest')rows=[...rows].reverse();$('#body-rows').innerHTML=rows.map((r,i)=>{const training=String(value(r,'Training'));let tone='tone-purple';if(i===0)tone='tone-feature';else if(/back|背/.test(training.toLowerCase()))tone='tone-cardio';else if(/chest|胸|shoulder|肩/.test(training.toLowerCase()))tone='tone-purple';else if(/leg|腿/.test(training.toLowerCase()))tone='tone-training';return `<article class="body-slip ${tone}"><div class="body-slip-date"><span>${String(i+1).padStart(2,'0')}</span><strong>${esc(dateOf(r))}</strong></div><div class="body-slip-weight"><b>${esc(value(r,'Weight (kg)'))}</b><small>kg</small></div><div class="body-slip-meta"><span>Training <strong>${esc(short(training,24))}</strong></span></div><div class="body-slip-copy"><p>${esc(short(value(r,'Notes'),160))}</p><button class="record-open" data-detail="body" data-index="${state.body.indexOf(r)}">Open record</button></div></article>`}).join('')}

dietPage=function(){main.innerHTML=`<section class="page archive-page diet-archive"><div class="archive-heading">${pageHeader('Diet Records','Energy and macros first. Full meals remain one deliberate click away.')}</div><div class="toolbar diet-toolbar"><input class="control search" id="diet-search" placeholder="Search notes, food or date..."><select class="control" id="diet-order"><option value="recent">Newest first</option><option value="oldest">Oldest first</option></select></div><div id="diet-rows" class="diet-slips"></div>${pager()}</section>`;renderDietRows()}
renderDietRows=function(q=$('#diet-search')?.value||''){let rows=state.diet.filter(r=>fuzzyMatch(r,q));if(selectedValue('diet-order')==='oldest')rows=[...rows].reverse();$('#diet-rows').innerHTML=rows.map((r,i)=>`<article class="diet-slip ${i%4===1?'slip-offset':''}"><span class="slip-index">${String(i+1).padStart(2,'0')}</span><h3>${esc(dateOf(r))}</h3><div class="macro-line"><strong>${esc(value(r,'Calories (kcal)'))}<small>kcal</small></strong><span>P ${esc(value(r,'Protein (g)'))}</span><span>C ${esc(value(r,'Carbs (g)'))}</span><span>F ${esc(value(r,'Fat (g)'))}</span></div><div class="diet-summary"><span>MEAL INDEX</span><p>${esc(short(value(r,'Food Summary'),68))}</p></div><button class="record-open" data-detail="diet" data-index="${state.diet.indexOf(r)}">Read detail</button></article>`).join('')}

checksPage=function(){main.innerHTML=`<section class="page page-grid checks-page"><div class="content">${pageHeader('Data Check','检查未解决的数据问题；只有明确的 Open 入口会打开详情。')}<div class="toolbar check-filters"><button class="btn btn-primary is-selected" data-check-filter="all">全部问题 &nbsp; ${issues.length}</button><button class="btn" data-check-filter="high">高 2</button><button class="btn" data-check-filter="medium">中 3</button><button class="btn" data-check-filter="low">低 1</button></div><div class="table-wrap check-table-wrap"><table class="check-table"><thead><tr><th>级别</th><th>日期</th><th>区域</th><th>问题</th><th>建议处理</th><th>详情</th></tr></thead><tbody>${issues.map((x,i)=>`<tr data-severity="${x[0].toLowerCase()}"><td><span class="severity ${x[0].toLowerCase()}">${x[0]}</span></td><td>${x[1]}</td><td>${x[2]}</td><td>${x[3]}</td><td>${x[4]}</td><td><button class="link issue-open" data-open-issue="${i}">??</button></td></tr>`).join('')}</tbody></table></div><div class="records-status" aria-live="polite">显示 ${issues.length} 个本地问题</div></div><aside class="rail"><section class="rail-section" style="margin-top:0"><span class="eyebrow">处理原则</span><h2 style="font:400 24px var(--serif)">由你确认，再进行修正</h2><p>网页查看端只展示问题详情，不会自动修改本地数据。</p></section><section class="rail-section"><span class="eyebrow">状态说明</span><div class="state-stack" style="margin-top:16px"><div class="state error">High · 优先核对</div><div class="state warning">Medium · 影响准确性</div><div class="state success">Low · 提示性问题</div></div></section></aside></section>`}

const compactSearch=value=>String(value??'').normalize('NFKC').toLowerCase().replace(/[\s\-_./\\，。；、:：()（）]+/g,'');
function dateParts(value){const match=String(value??'').match(/(?:\d{4}[-/.])?(\d{1,2})[-/.](\d{1,2})/);return match?[Number(match[1]),Number(match[2])]:null}
function fuzzyMatch(record,query){const raw=String(query??'').trim();if(!raw)return true;const compact=compactSearch(JSON.stringify(record)),terms=raw.split(/\s+/).map(compactSearch).filter(Boolean);if(terms.every(term=>compact.includes(term)))return true;const wanted=dateParts(raw),actual=dateParts(dateOf(record));return Boolean(wanted&&actual&&wanted[0]===actual[0]&&wanted[1]===actual[1])}
function latestRecordDate(rows){return rows.reduce((latest,row)=>{const date=new Date(`${dateOf(row)}T00:00:00`);return Number.isNaN(date.valueOf())||date<latest?latest:date},new Date(0))}
function withinDays(row,days,rows){if(!days)return true;const latest=latestRecordDate(rows),date=new Date(`${dateOf(row)}T00:00:00`);return !Number.isNaN(date.valueOf())&&(latest-date)/86400000<days}
const selectedValue=id=>document.getElementById(id)?.value||'all';

quickPage=function(){main.innerHTML=`<section class="page entry-page entry-editorial"><header class="entry-header"><div class="entry-title-lockup"><span class="eyebrow">02 / Unavailable</span><h1 class="page-title"><span>Write</span> the day.</h1><p class="page-subtitle">Freeform first. <b>Structure follows</b> after review.</p><div class="entry-rule"><span>LOCAL NOTE</span><i></i><span>PRIVATE ARCHIVE</span></div></div><button class="home-text-link" data-go="home">← Unavailable</button></header><div class="entry-spread"><article class="capture"><span class="eyebrow">FREEFORM → STRUCTURED</span><h2>Raw first.<br><em>Structure second.</em></h2><textarea id="raw-entry" placeholder="写下今天的任何内容…"></textarea><div class="actions"><button class="btn btn-primary" id="parse">Unavailable →</button><button class="btn btn-light" data-mock="Unavailable">Undo last save</button></div><p class="phase">Read-only Web preview. Formal writes remain in the stable desktop app.</p></article><aside class="entry-aside">${statusPanel()}${recentPanel()}</aside></div></section>`}

function compactEntryAside(){const t=state.today,b=t.body||{},d=t.diet||{},tr=t.training||{},previous=state.recent.filter(r=>!t.date||String(r.date||'')!==String(t.date)).slice(0,3);return `<aside class="entry-compact-aside"><section class="entry-today-compact material-frosted edge-highlight"><span class="receipt-pin" aria-hidden="true"></span><span class="eyebrow">LATEST ENTRY / ${esc(t.date||'NO RECORD')}</span><div class="today-weight"><strong>${esc(value(b,'Weight (kg)'))}</strong><small>kg</small></div><div class="today-facts"><span><b>${esc(value(d,'Calories (kcal)'))}</b> kcal</span><span><b>${esc(value(tr,'split','Split'))}</b> training</span></div></section><section class="entry-recent-compact archive-slip"><div class="rail-head"><span class="eyebrow" aria-hidden="true"></span></div>${previous.map((r,i)=>`<div class="compact-record archive-card interactive-lift" style="--slip-index:${i}"><span>0${i+1}</span><div><strong>${esc(r.date)}</strong><small>${esc(r.weight||'—')} kg · ${esc(r.calories||'—')} kcal<br>${esc(r.split||'Rest')}</small></div><button data-record="${esc(r.date)}">Open</button></div>`).join('')||'<p class="empty-copy">No recent records.</p>'}<button class="home-text-link entry-recent-view-all" data-go="body">View all →</button></section></aside>`}
quickPage=function(){main.innerHTML=`<section class="page entry-page entry-editorial entry-single-screen entry-workbench-page"><div class="entry-desk-atmosphere" aria-hidden="true"></div><header class="entry-header"><div class="entry-title-lockup"><span class="eyebrow">02 / Unavailable</span><h1 class="page-title"><span>Write</span> the day.</h1><p class="page-subtitle">Freeform first. <b>Structure follows</b> after review.</p><div class="entry-rule"><span>LOCAL NOTE</span><i></i><span>PRIVATE ARCHIVE</span></div></div><button class="home-text-link" data-go="home">← Unavailable</button></header><div class="entry-spread entry-workbench"><article class="capture material-slab edge-highlight"><span class="capture-tab">02 / LOCAL CAPTURE</span><span class="eyebrow">FREEFORM → STRUCTURED</span><h2>Raw first. <em>Structure second.</em></h2><textarea id="raw-entry" placeholder="写下今天的任何内容…"></textarea><div class="actions"><button class="btn btn-primary interactive-lift interactive-press" id="parse">Unavailable <span>→</span></button><button class="btn btn-light material-control interactive-press" data-undo>Undo last save</button></div><p class="phase">Review first; confirmed saves create a local backup automatically.</p></article>${compactEntryAside()}<aside class="entry-save-float material-frosted"><i></i><div><span>LOCAL-FIRST</span><strong>Ready to capture</strong><small>Changes are saved only after Review.</small></div><b>✓</b></aside></div></section>`}

bodyPage=function(){main.innerHTML=`<section class="page archive-page body-archive"><div class="body-folio">BODY / LOCAL ARCHIVE / PRIVATE</div><div class="archive-heading">${pageHeader('Body Records','Daily measurements as personal body slips, with notes kept readable.')}</div><div class="body-controls-row"><div class="toolbar body-toolbar"><input class="control search" id="body-search" placeholder="Search notes or date..."><select class="control" id="body-time"><option value="0">All time</option><option value="7">Recent 7 days</option><option value="14">Recent 14 days</option><option value="30">Recent 30 days</option></select><select class="control" id="body-order"><option value="recent">Newest first</option><option value="oldest">Oldest first</option></select></div><div id="body-weight-slot" class="body-weight-slot"></div></div><div id="body-rows" class="body-ledger"></div>${pager()}</section>`;renderBodyRows()}
function stableHash(value){let hash=2166136261;for(const char of String(value||'')){hash^=char.charCodeAt(0);hash=Math.imul(hash,16777619)}return hash>>>0}
function bodySlipKey(record){return record.id||record.record_id||record.uuid||[dateOf(record),value(record,'Weight (kg)'),value(record,'Training'),value(record,'Notes')].join('|')}
function bodySlipClasses(record,avoidTone=''){const tones=['tone-feature','tone-training','tone-rest','tone-cardio','tone-purple'],hash=stableHash(bodySlipKey(record)),baseIndex=hash%tones.length,tone=tones[baseIndex]===avoidTone?tones[(baseIndex+1)%tones.length]:tones[baseIndex],offset=Math.floor(hash/tones.length)%3;return `${tone} body-offset-${offset}`}
renderBodyRows=function(q=$('#body-search')?.value||''){const days=Number(selectedValue('body-time')||0);let rows=state.body.filter(r=>fuzzyMatch(r,q)).filter(r=>withinDays(r,days,state.body));if(selectedValue('body-order')==='oldest')rows=[...rows].reverse();let previousTone='';$('#body-rows').innerHTML=rows.map((r,i)=>{const training=String(value(r,'Training')),classes=bodySlipClasses(r,previousTone);previousTone=classes.split(' ')[0];return `<article class="body-slip ${classes}" data-record-date="${esc(dateOf(r))}"><div class="body-slip-date"><span>${String(i+1).padStart(2,'0')}</span><strong>${esc(dateOf(r))}</strong></div><div class="body-slip-weight"><b>${esc(value(r,'Weight (kg)'))}</b><small>kg</small></div><div class="body-slip-meta"><span>Training <strong>${esc(short(training,24))}</strong></span></div><div class="body-slip-copy"><p>${esc(short(value(r,'Notes'),160))}</p><button class="record-open" data-detail="body" data-index="${state.body.indexOf(r)}">Open record</button></div></article>`}).join('')||'<p class="empty-note">No body records match this search.</p>'}

dietPage=function(){main.innerHTML=`<section class="page archive-page diet-archive"><div class="archive-heading">${pageHeader('Diet Records','Energy and macros first. Full meals remain one deliberate click away.')}</div><div class="toolbar diet-toolbar"><input class="control search" id="diet-search" placeholder="Search notes, food or date..."><select class="control" id="diet-order"><option value="recent">Newest first</option><option value="oldest">Oldest first</option></select></div><div id="diet-rows" class="diet-slips"></div>${pager()}</section>`;renderDietRows()}
renderDietRows=function(q=$('#diet-search')?.value||''){let rows=state.diet.filter(r=>fuzzyMatch(r,q));if(selectedValue('diet-order')==='oldest')rows=[...rows].reverse();$('#diet-rows').innerHTML=rows.map((r,i)=>`<article class="diet-slip ${i%4===1?'slip-offset':''}" data-record-date="${esc(dateOf(r))}"><span class="slip-index">${String(i+1).padStart(2,'0')}</span><h3>${esc(dateOf(r))}</h3><div class="macro-line"><strong>${esc(value(r,'Calories (kcal)'))}<small>kcal</small></strong><span>P ${esc(value(r,'Protein (g)'))}</span><span>C ${esc(value(r,'Carbs (g)'))}</span><span>F ${esc(value(r,'Fat (g)'))}</span></div><div class="diet-summary"><span>MEAL INDEX</span><p>${esc(short(value(r,'Food Summary'),68))}</p></div><button class="record-open" data-detail="diet" data-index="${state.diet.indexOf(r)}">Read detail</button></article>`).join('')||'<p class="empty-note">No diet records match this search.</p>'}

function movementArtFor(group){const key=String(group||'').toLowerCase();if(/cardio|aerobic|有氧/.test(key))return'body-themes-v2/cardio.png';if(/glute|臀/.test(key))return'body-themes-v2/glutes.png';if(/shoulder|肩/.test(key))return'body-themes-v2/shoulders.png';if(/arms?|biceps|triceps|手臂|二头|三头/.test(key))return'body-themes-v2/arms.png';if(/back|pull|背/.test(key))return'body-themes-v2/back.png';if(/chest|胸/.test(key))return'body-themes-v2/chest.png';if(/leg|lower|腿/.test(key))return'body-themes-v2/legs.png';return'movement-art-core.png'}
function movementGroupClass(group){const key=String(group||'').toLowerCase();if(/cardio|aerobic|有氧/.test(key))return'group-cardio';if(/glute|臀/.test(key))return'group-glutes';if(/leg|lower|腿/.test(key))return'group-legs';if(/shoulder|肩/.test(key))return'group-shoulders';if(/back|pull|背/.test(key))return'group-back';if(/chest|胸/.test(key))return'group-chest';if(/arms?|biceps|triceps|手臂|二头|三头/.test(key))return'group-arms';return'group-core'}
function layoutMovementMasonry(){const grid=$('.movement-groups');if(!grid)return;const groups=[...grid.children].filter(node=>node.classList.contains('movement-group'));groups.forEach(group=>group.style.gridRowEnd='auto');if(matchMedia('(max-width:1120px)').matches)return;const style=getComputedStyle(grid),rowHeight=parseFloat(style.gridAutoRows)||4,gap=parseFloat(style.rowGap)||14;groups.forEach(group=>{group.style.gridRowEnd=`span ${Math.max(1,Math.ceil((group.getBoundingClientRect().height+gap)/(rowHeight+gap)))}`})}
renderMovementDirectory=function(q=''){
  clearMovementIndexPreviousPreview();
  const target=$('#movement-list');if(!target)return;
  const english=document.documentElement.dataset.flUiLanguage==='en';
  const usage=m=>state.movementUsage[String(m.movement_id||'')]?.count||0;
  const focus=m=>Number(m.focus_rank||0)>0||Boolean(m.pinned),rank=m=>Number(m.focus_rank||0)>0?Number(m.focus_rank):Number.MAX_SAFE_INTEGER;
  const activeCategories=new Set((state.trainingOrganization?.movement_categories||[]).filter(item=>item.active!==false).map(item=>String(item.category_id)));
  const rows=state.movements.filter(m=>usage(m)>0&&fuzzyMatch(m,q)&&(!activeCategories.size||activeCategories.has(String(m.movement_category_id||m.progress_category_id||movementCategoryForGroup(m.muscle_group)||'')))).sort((a,b)=>Number(focus(b))-Number(focus(a))||rank(a)-rank(b)||usage(b)-usage(a)||String(a.display_name||'').localeCompare(String(b.display_name||''),'zh-CN'));
  const groups=new Map();for(const m of rows){const key=m.muscle_group||'Other';if(!groups.has(key))groups.set(key,[]);groups.get(key).push(m)}
  const activeCategoryRows=(state.trainingOrganization?.movement_categories||[]).filter(item=>item.active!==false).sort((a,b)=>Boolean(b.pinned)-Boolean(a.pinned)||Number(a.sort_order||9999)-Number(b.sort_order||9999));
  const categoryToGroup={glutes:'Glutes',cardio:'Cardio',shoulders:'Shoulder',chest:'Chest',back:'Back',legs:'Legs',arms:'Arms',core:'Core'};
  for(const category of activeCategoryRows){const group=categoryToGroup[String(category.category_id||'')];if(group&&!groups.has(group))groups.set(group,[])}
  const categoryById=new Map((state.trainingOrganization?.movement_categories||[]).map(item=>[String(item.category_id),item]));
  const ordered=[...groups.entries()].sort((a,b)=>{const ac=categoryById.get(movementCategoryForGroup(a[0]))||{},bc=categoryById.get(movementCategoryForGroup(b[0]))||{};if(Boolean(ac.pinned)!==Boolean(bc.pinned))return Boolean(bc.pinned)-Boolean(ac.pinned);const order=Number(ac.sort_order||9999)-Number(bc.sort_order||9999);return order||b[1].reduce((n,m)=>n+usage(m),0)-a[1].reduce((n,m)=>n+usage(m),0)});
  target.innerHTML=ordered.map(([group,items],groupIndex)=>{
    const groupTitle=english?group:groupLabel(group),groupSubtitle=english?groupLabel(group):group,countLabel=english?`${items.length} movements`:`${items.length} 个动作`,focusLabel=english?'★ FOCUS':'★ 重点',previewLabel=english?'HOLD · LAST SESSION':'按住 · 查看最近训练',emptyTitle=english?'Module enabled':'模块已启用',emptyCopy=english?'No movement history yet. It will appear after the first related training.':'暂无动作历史，完成首次相关训练后会在这里展开。';
    const header=`<img class="movement-group-art" src="assets/${movementArtFor(group)}" alt="" aria-hidden="true"><header><span class="group-number">${String(groupIndex+1).padStart(2,'0')}</span><div><h2>${esc(groupTitle)}</h2><p>${esc(groupSubtitle)} · ${esc(countLabel)}</p></div></header>`;
     return `<section class="movement-group ${items.length?'':'is-empty'} group-${groupIndex%3} ${movementGroupClass(group)}">${header}<div class="movement-mosaic">${items.length?items.map((m,i)=>{const movementId=String(m.movement_id||''),names=movementNamesForUi(m),count=usage(m),hasPreview=count>0;return `<button class="movement-tile ${i===0&&count?'tile-lead':count>=4?'tile-wide':'tile-slip'} ${hasPreview?'has-index-previous-record':''}" data-select-movement-id="${esc(movementId)}" data-index-preview-movement-id="${esc(movementId)}">${m.pinned?`<span class="movement-focus-mark">${focusLabel}</span>`:''}<span class="tile-count">${count} sessions</span>${hasPreview?`<span class="movement-index-preview-cue">${previewLabel}</span>`:''}<strong>${esc(names.primary)}</strong><small>${esc(names.secondary)}</small>${i===0&&m.notes?`<p class="movement-definition-note">${esc(short(m.notes,90))}</p>`:''}<em>Open trajectory →</em></button>`}).join(''):`<div class="movement-empty-signal"><strong>${emptyTitle}</strong><span>${emptyCopy}</span></div>`}</div></section>`
  }).join('')||'<p class="empty-note">No matching movements.</p>';
  const count=$('.result-count');if(count)count.textContent=english?`${rows.length} movements`:`${rows.length} 个动作`;
  requestAnimationFrame(()=>requestAnimationFrame(layoutMovementMasonry));
}
loadMovementFocus=async function(movementId){state.movementSelection=String(movementId||'');main.innerHTML=`<section class="page movement-detail-page"><button class="movement-back" data-movement-index>← Movement Index</button><div id="movement-focus"><div class="loading-page"><i></i><p>Loading recorded history…</p></div></div></section>`;const focus=$('#movement-focus');try{let payload=state.movementUsage[String(movementId)]?.payload;if(!payload)payload=await api(`/api/movement-history?movement_id=${encodeURIComponent(movementId)}&limit=50`);state.movementHistory=payload;if(!payload.movement){navigate('movements',{}, {replace:true,context:null});return}const movement=payload.movement||{},history=payload.progress_history||payload.history||[],latest=history[0],earliest=history[history.length-1],art=movementArtFor(movement.muscle_group);focus.innerHTML=`<div class="movement-detail-compact"><img src="assets/${art}" alt="" aria-hidden="true"><div><span class="eyebrow">RECORDED TRAJECTORY</span><h1>${esc(movement.display_name||movementId)}</h1><p>${esc(movement.english_name||movement.muscle_group||'Recorded movement')}</p></div><div class="movement-detail-stats"><span><b>${history.length}</b> sessions</span><span><b>${esc(latest?.date||'—')}</b> latest</span><span><b>${esc(earliest?.date||'—')}</b> first</span></div></div><div class="trajectory-heading"><span class="eyebrow">PROGRESSION / NEWEST FIRST</span><h2>Training trajectory</h2><p>每次训练的负重、次数、组数和备注按时间展开。</p></div><div class="trajectory"><div class="trajectory-line"></div>${history.map((r,i)=>`<article class="trajectory-entry ${i===0?'is-latest':''}"><div class="trajectory-marker">${String(i+1).padStart(2,'0')}</div><button class="history-date history-date-link" data-training-date="${esc(r.date||'')}" data-training-movement-id="${esc(movement.movement_id||movementId)}"><strong>${esc(r.date||'?')}</strong><small>Day ${esc(r.training_day??'?')} ? Ex ${esc(r.order??'?')}</small></button><div class="history-content"><h3>${esc((r.sets_lines||[]).join(' · ')||'Recorded without structured sets')}</h3>${r.notes?`<p>${esc(r.notes)}</p>`:''}</div></article>`).join('')||'<div class="empty-copy"><h3>No history yet</h3><p>This movement exists in the dictionary but has no recorded sessions.</p></div>'}</div>`}catch{focus.innerHTML='<div class="empty-copy"><h3>History unavailable</h3><p>The local read-only service could not load this movement.</p></div>'}}

function movementRecordMetrics(record){
  const superset=Array.isArray(record?.organization_relations)&&record.organization_relations.some(relation=>String(relation?.type||'').toLowerCase()==='superset');
  if(record?.metrics){
    const metrics=record.metrics;
    return {
      maxLoad:Number(metrics.max_weight||0),
      volume:Number(metrics.volume||0),
      totalReps:Number(metrics.total_reps||0),
      comparable:Boolean(metrics.has_structured_sets),
      complex:Boolean(metrics.has_complex_sets),
      structured:Boolean(metrics.has_structured_sets),
      superset
    };
  }
  let maxLoad=0,volume=0,totalReps=0,comparable=false,complex=false,structured=false;
  for(const line of record.sets_lines||[]){
    const groupMatch=line.match(/[×x*]\s*(\d+)\s*组?\s*$/i),groupCount=groupMatch?Number(groupMatch[1]):1;
    if(/\+/.test(line)){
      complex=true;
      const pattern=/(\d+(?:\.\d+)?)\s*(?:kg)?\s*[×x*]\s*(\d+)/gi;
      let match,segmentHits=0;
      while((match=pattern.exec(line))){
        const load=Number(match[1]),reps=Number(match[2]);
        if(reps<=0||groupCount<=0)continue;
        segmentHits++;maxLoad=Math.max(maxLoad,load);volume+=load*reps*groupCount;totalReps+=reps*groupCount;
      }
      structured=structured||segmentHits>0;comparable=comparable||segmentHits>0;
      continue;
    }
    const pattern=/(\d+(?:\.\d+)?)\s*(?:kg)?\s*[×x*]\s*(\d+)\s*[×x*]\s*(\d+)/gi;
    let match;
    while((match=pattern.exec(line))){
      const load=Number(match[1]),reps=Number(match[2]),sets=Number(match[3]);
      if(reps<=0||sets<=0)continue;
      structured=true;comparable=true;maxLoad=Math.max(maxLoad,load);volume+=load*reps*sets;totalReps+=reps*sets;
    }
    if(/自重|body\s*weight|\bbw\b/i.test(line)){
      const body=line.match(/[×x*]\s*(\d+)\s*[×x*]\s*(\d+)/i);
      if(body){
        const reps=Number(body[1]),sets=Number(body[2]);
        if(reps>0&&sets>0){structured=true;comparable=true;totalReps+=reps*sets;volume+=reps*sets;}
      }
    }
  }
  return {maxLoad,volume,totalReps,comparable,complex,structured,superset};
}
function movementProgressChart(history){
  const available=history.map(record=>({...record,...movementRecordMetrics(record)})).filter(record=>!record.superset&&record.structured&&(record.volume>0||(record.maxLoad===0&&record.totalReps>0))).slice(0,8).reverse();
  if(!available.length){
    return `<section class="movement-progress-panel is-empty"><div class="progress-copy"><span class="eyebrow">RECENT 8 / VISUAL SUMMARY</span><h2>暂无可统计的训练数据</h2><p>复杂组会按重量与对应次数计算容量；超级组记录不计入图表。</p></div><p class="progress-empty-copy">No eligible training data yet</p></section>`;
  }
  const useLoad=available.at(-1).maxLoad>0;
  const records=available.filter(record=>useLoad?record.maxLoad>0:record.maxLoad===0);
  const values=records.map(record=>useLoad?record.maxLoad:record.totalReps);
  const volumes=records.map(record=>record.volume),maxValue=Math.max(...values,1),maxVolume=Math.max(...volumes,1),left=48,right=682,width=right-left,step=records.length>1?width/(records.length-1):0;
  const points=records.map((record,index)=>`${left+index*step},${145-(values[index]/maxValue)*92}`).join(' ');
  const bars=records.map((record,index)=>{const height=(volumes[index]/maxVolume)*70,x=left+index*step-12;return `<rect data-chart-value="${volumes[index]}" x="${x}" y="${160-height}" width="24" height="${height}" rx="4"></rect>`}).join('');
  const dots=records.map((record,index)=>`<circle data-chart-value="${values[index]}" data-chart-capacity="${volumes[index]}" cx="${left+index*step}" cy="${145-(values[index]/maxValue)*92}" r="5"></circle>`).join('');
  const labels=records.map((record,index)=>`<text x="${left+index*step}" y="194" text-anchor="middle">${esc(String(record.date||'').slice(5))}</text>`).join('');
  const latest=values.at(-1),previous=values.length>1?values.at(-2):null,delta=previous===null?null:Math.round((latest-previous)*10)/10,unit=useLoad?'kg':'reps';
  const description=useLoad?'折线表示每次训练的最大重量；柱形表示该动作本次训练容量。复杂组按各重量 × 对应次数 × 组数累加，超级组记录不计入。':'自重动作以总次数显示折线、以训练容量显示柱形；超级组记录不计入。';
  return `<section class="movement-progress-panel"><div class="progress-copy"><span class="eyebrow">RECENT 8 / VISUAL SUMMARY</span><h2>Recent change</h2><p>${description}</p></div><div class="progress-signal"><span>Latest max</span><strong>${latest} ${unit}</strong>${delta===null?'':`<small class="${delta>0?'up':delta<0?'down':''}">${delta>0?'+':''}${delta} vs previous</small>`}</div><svg class="progress-chart" data-chart-metric="${useLoad?'load':'reps'}" viewBox="0 0 730 220" role="img" aria-label="Recent movement maximum and capacity progression"><g class="chart-grid"><line x1="48" y1="53" x2="682" y2="53"></line><line x1="48" y1="99" x2="682" y2="99"></line><line x1="48" y1="145" x2="682" y2="145"></line></g><g class="volume-bars">${bars}</g><polyline class="load-line" points="${points}"></polyline><g class="load-dots">${dots}</g><g class="chart-labels">${labels}</g></svg></section>`;
}
loadMovementFocus=async function(movementId){state.movementSelection=String(movementId||'');main.innerHTML=`<section class="page movement-detail-page"><button class="movement-back" data-movement-index>← Movement Index</button><div id="movement-focus"><div class="loading-page"><i></i><p>Loading recorded history…</p></div></div></section>`;const focus=$('#movement-focus');try{let payload=state.movementUsage[String(movementId)]?.payload;if(!payload)payload=await api(`/api/movement-history?movement_id=${encodeURIComponent(movementId)}&limit=50`);state.movementHistory=payload;if(!payload.movement){navigate('movements',{}, {replace:true});return}const movement=payload.movement||{},progressHistory=Array.isArray(payload.progress_history)?payload.progress_history:[],history=Array.isArray(payload.history)?payload.history:[],latest=progressHistory[0],earliest=progressHistory[progressHistory.length-1],art=movementArtFor(movement.muscle_group),groupClass=movementGroupClass(movement.muscle_group),names=movementNamesForUi(movement),display=names.primary,longClass=String(display).length>5?'is-long':'';focus.innerHTML=`<div class="movement-detail-compact ${groupClass} ${longClass}"><img class="movement-detail-art" src="assets/${art}" alt="" aria-hidden="true"><div class="movement-detail-title"><span class="eyebrow">RECORDED TRAJECTORY</span><h1>${esc(display)}</h1><p>${esc(names.secondary)}</p></div><div class="movement-detail-stats"><span><b>${progressHistory.length}</b> effective sessions</span><span><b>${esc(latest?.date||'—')}</b> latest</span><span><b>${esc(earliest?.date||'—')}</b> first</span></div></div>${movementProgressChart(progressHistory)}<div class="trajectory-heading"><span class="eyebrow">FULL HISTORY / NEWEST FIRST</span><h2>Training history</h2><p>完整动作历史保留所有实例；成长图表只读取有效轨迹。</p></div><div class="trajectory">${history.map((r,i)=>{const sets=(r.sets_lines||[]).filter(Boolean);return `<article class="trajectory-entry ${i===0?'is-latest':''} ${r.exclude_from_progress?'is-progress-excluded':''}"><button class="history-date history-date-link" data-training-date="${esc(r.date||'')}" data-training-movement-id="${esc(movement.movement_id||movementId)}"><strong>${esc(r.date||'?')}</strong>${r.exclude_from_progress?'<small>不计入成长轨迹</small>':''}</button><div class="history-content">${sets.length?`<h3>${esc(sets.join(' · '))}</h3>`:''}${r.notes?`<p>${esc(r.notes)}</p>`:''}</div></article>`}).join('')||'<div class="empty-copy"><h3>No history yet</h3><p>This movement exists in the dictionary but has no recorded sessions.</p></div>'}</div>`}catch{focus.innerHTML='<div class="empty-copy"><h3>History unavailable</h3><p>The local read-only service could not load this movement.</p></div>'}}

async function postApi(path,payload,timeout=API_TIMEOUT_MS){const response=await fetchWithTimeout(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)},timeout);const data=await response.json().catch(()=>({error:'Invalid local service response.'}));if(!response.ok){const error=Error(data.error||`Request failed (${response.status})`);error.status=response.status;error.payload=data;throw error}return data}
