const longRecordFields=new Set(['Food Summary','Raw Record','Standardized Summary','Notes']);
function realRecordDetail(kind,index){
  const rows={body:state.body,diet:state.diet,training:state.training},record=rows[kind]?.[index];
  if(!record)return;
  const fields=recordEditFields[kind]||[];
  const formFields=fields.map(field=>{const control=longRecordFields.has(field)?`<textarea name="${esc(field)}" rows="${field==='Notes'?3:5}">${esc(record[field]??'')}</textarea>`:`<input name="${esc(field)}" value="${esc(record[field]??'')}" ${field==='Date'?'type="date"':''}>`;return `<label class="${longRecordFields.has(field)?'is-wide':''}"><span>${esc(field)}</span>${control}</label>`}).join('');
  const content=`<form id="record-edit-form" class="record-edit-form" data-record-type="${kind}" data-record-id="${esc(record.id||'')}" data-revision="${esc(record.revision||1)}">${formFields}${fields.includes('Date')?'<label><span>日期变更范围</span><select name="move_scope"><option value="record">仅移动当前记录</option><option value="day">移动整日关联记录</option></select></label>':''}<p class="record-edit-note">保存前自动创建成对备份。原始训练文本请使用“差异预览”后确认，不允许静默覆盖。</p></form>`;
  modal(`${kind[0].toUpperCase()+kind.slice(1)} Record`,content,{light:kind==='diet',actions:`<button class="btn" data-close>取消</button><button class="btn btn-primary" data-record-save>保存修改</button>`});
}
