async function saveRecordEdit(){const form=$('#record-edit-form');if(!form)return;const values=Object.fromEntries(new FormData(form).entries()),moveScope=values.move_scope||'record';delete values.move_scope;const button=$('[data-record-save]');button.disabled=true;try{const result=await postApi('/api/record/update',{record_type:form.dataset.recordType,record_id:form.dataset.recordId,expected_revision:Number(form.dataset.revision||1),values,move_scope:moveScope});root.innerHTML='';if(form.dataset.recordType==='training'&&result.status!=='NO_CHANGES')invalidateMovementUsage();await refreshWebState();navigate(form.dataset.recordType);showSaveReceipt(result)}catch(error){button.disabled=false;showSaveReceipt(null,error.message||'记录保存失败。')}}
