function reviewSetCount(item){if(typeof item!=='object'||item===null)return 0;const raw=item.set_count??item.sets;if(Array.isArray(raw))return raw.reduce((total,nested)=>total+reviewSetCount(nested),0);if(raw===undefined||raw===null||raw==='')return 1;const count=Number(raw);return Number.isFinite(count)&&count>=0?count:1}
