function reviewSetText(item){if(typeof item!=='object'||item===null)return String(item||'');if(Array.isArray(item.segments)&&item.segments.length){const body=item.segments.map(segment=>`${segment.weight_text||(Number(segment.weight)>0?`${segment.weight}kg`:'自重')} × ${segment.reps??'-'}`).join(' + ');const count=reviewSetCount(item);return `${body}${count>1?` × ${count}组`:''}`}const load=item.weight_text||item.load||item.weight_label||(Number(item.weight)>0?`${item.weight}kg`:'自重'),count=reviewSetCount(item);return `${load} × ${item.reps??'-'} × ${count}`}
