async function autoSyncAfterSave(){
  let latestStatus=null;
  try{
    latestStatus=await api('/api/cloud-sync/status');
    state.syncStatus=latestStatus;
    updateSyncNav();
    if(latestStatus.auto_sync_enabled===false)return {status:'AUTO_SYNC_DISABLED',syncStatus:latestStatus};
    if(!latestStatus.upload_provider_ready)return {status:'AUTO_SYNC_NOT_CONFIGURED',syncStatus:latestStatus};
    const response=await postApi('/api/cloud-sync/sync',{trigger:'auto_save'},CLOUD_SYNC_TIMEOUT_MS);
    const result=response.sync_result||{};
    latestStatus=await api('/api/cloud-sync/status');
    state.syncStatus={...latestStatus,sync_result:result};
    updateSyncNav();
    if(latestStatus.sync_status==='SYNCED')return {status:'SYNCED',reconciled:!['SYNCED','NO_CHANGES'].includes(result.status),syncStatus:state.syncStatus};
    if(['UPLOAD_FAILED','CLOUD_MISMATCH','NOT_CONFIGURED'].includes(result.status))return {status:result.status,syncStatus:state.syncStatus};
    return {status:'PENDING',syncStatus:state.syncStatus};
  }catch(error){
    console.warn('[Daily Entry] auto-sync response was not confirmed',error);
    for(let attempt=0;attempt<4;attempt++){
      if(attempt)await new Promise(resolve=>window.setTimeout(resolve,1200*attempt));
      try{
        latestStatus=await api('/api/cloud-sync/status');
        state.syncStatus=latestStatus;
        updateSyncNav();
        if(latestStatus.sync_status==='SYNCED')return {status:'SYNCED',reconciled:true,syncStatus:latestStatus};
        if(['UPLOAD_FAILED','CLOUD_MISMATCH','NOT_CONFIGURED'].includes(latestStatus.sync_status))return {status:latestStatus.sync_status,syncStatus:latestStatus};
      }catch(statusError){console.warn('[Daily Entry] auto-sync status reconciliation attempt failed',attempt+1,statusError)}
    }
    state.syncStatus={...(state.syncStatus||{}),sync_status:'SYNC_ERROR',payload_stale:true};
    updateSyncNav();
    return {status:'UNKNOWN',syncStatus:state.syncStatus};
  }
}
function autoSyncOutcomeMessage(outcome){const status=String(outcome?.status||'UNKNOWN');if(status==='SYNCED')return outcome?.reconciled?'记录已保存；自动同步结果已复核为成功。':'记录已保存，并已自动同步到云端。';if(status==='AUTO_SYNC_DISABLED')return '记录已保存；自动同步未启用，云端副本等待手动同步。';if(status==='AUTO_SYNC_NOT_CONFIGURED')return '记录已保存；自动同步未配置，云端副本等待手动同步。';if(status==='PENDING')return '记录已保存；云端尚未确认同步，请在 Cloud Sync 中查看状态。';if(status==='UPLOAD_FAILED'||status==='CLOUD_MISMATCH'||status==='NOT_CONFIGURED')return `记录已保存；云端同步未完成（${status}），可在 Cloud Sync 中手动重试。`;return '记录已保存；自动同步结果暂无法确认，请在 Cloud Sync 中查看最终状态。'}
function showAutoSyncReceipt(outcome){const receipt=$('#save-receipt');if(!receipt)return;clearTimeout(state.receiptTimer);const message=autoSyncOutcomeMessage(outcome),ok=outcome?.status==='SYNCED';receipt.dataset.syncState=ok?'synced':'attention';receipt.innerHTML=`<span>${ok?'LOCAL + CLOUD CONFIRMED':'LOCAL SAVED · CLOUD STATUS'}</span><strong>${esc(message)}</strong>`;receipt.classList.add('is-visible');state.receiptTimer=setTimeout(()=>receipt.classList.remove('is-visible'),ok?7000:10000)}
function updateSyncNav(){
  const nav=$('[data-sync-nav-entry]'),marker=nav?.querySelector('.sync-nav-status');
  if(!nav||!marker)return;
  const code=String(state.syncStatus?.sync_status||'').toUpperCase();
  const pending=['LOCAL_NEWER','LOCAL_CHANGES','READY'].includes(code)||state.syncStatus?.payload_stale===true;
  const failed=['UPLOAD_FAILED','CLOUD_MISMATCH','SYNC_ERROR'].includes(code);
  const visible=pending||failed;
  const copy=failed?'最近一次云同步未完成':'本地记录尚未同步到只读云副本';
  nav.hidden=!visible;
  marker.hidden=!visible;
  marker.className=`health-nav-status sync-nav-status${pending?' sync-pending':failed?' sync-error':''}`;
  if(!visible){marker.textContent='';nav.removeAttribute('title');nav.setAttribute('aria-label','查看云同步状态');return}
  marker.textContent=failed?'!':'•';
  nav.title=copy;
  nav.setAttribute('aria-label',copy);
}
function showSaveReceipt(result,error){const receipt=$('#save-receipt');if(!receipt)return;clearTimeout(state.receiptTimer);if(error){receipt.innerHTML=`<span>SAVE NEEDS ATTENTION</span><strong>${esc(error)}</strong>`}else if(result.status==='NO_CHANGES'){receipt.innerHTML='<span>NO CHANGES TO SAVE</span>'}else{const verb=result.status==='UPDATED'?'UPDATED':'SAVED',facts=[],date=result.date||result.record?.Date||result.history?.date||'';if(result.saved_movements)facts.push(`${result.saved_movements} movements · ${result.working_sets||0} working sets`);if(Number(result.progress_excluded_count||0)>0)facts.push(`${result.progress_excluded_count} 个动作仅保留训练记录`);if(result.body_updated&&result.diet_updated)facts.push('Body and diet updated');else if(result.training_updated)facts.push('Training updated');receipt.innerHTML=`<span>${esc(String(date||'RECORD').toUpperCase())} ${verb}</span>${facts.map(x=>`<strong>${esc(x)}</strong>`).join('')}${(state.syncStatus?.payload_stale===true||['LOCAL_NEWER','LOCAL_CHANGES','READY'].includes(state.syncStatus?.sync_status))?'<small>Cloud copy pending</small>':''}`};receipt.classList.add('is-visible');state.receiptTimer=setTimeout(()=>receipt.classList.remove('is-visible'),4200)}
async function refreshWebState(){const slots=['today','recent','body','diet','training','movements','dictionary','movementGroups','syncStatus','trainingOrganization','dataModuleCatalog','dataModuleExport'];const requests=[api('/api/today'),api('/api/recent?limit=5'),api('/api/body?limit=100'),api('/api/diet?limit=100'),api('/api/training?limit=100'),api('/api/movements?limit=100'),api('/api/dictionary'),api('/api/movement-groups'),api('/api/cloud-sync/status'),api('/api/training-organization'),api('/api/data-modules/product-catalog'),api('/api/data-modules/export')];const results=await Promise.allSettled(requests);results.forEach((result,index)=>{if(result.status==='fulfilled')state[slots[index]]=result.value});state.dataModulesReady=results[10]?.status==='fulfilled'&&results[11]?.status==='fulfilled';updateSyncNav();publishGuardianBodyRegions();window.dispatchEvent(new CustomEvent('fitness-ledger:data-ready',{detail:{dataModulesReady:state.dataModulesReady}}));if(results[5]?.status==='fulfilled'&&state.view==='movements'&&state.usageLoaded)void loadMovementUsage();const requiredFailure=results.slice(0,10).find(result=>result.status==='rejected');if(requiredFailure)throw requiredFailure.reason}
async function saveWebReview(saveMode=null){
  if(state.saving)return;
  const review=collectReviewForm();
  if(!review)return;
  if(reviewDuplicateCount()&&!saveMode){openSaveModeDialog();return}
  state.saving=true;
  const button=$('[data-review-save]');
  if(button){button.disabled=true;button.textContent='正在保存…'}
  try{
    let result;
    try{
      const naturalLanguageReview=state.reviewSource==='natural_language_import'||state.reviewSource==='daily_entry_natural_language';
      result=await postApi(naturalLanguageReview?'/api/import/confirm':'/api/save',{review_id:state.reviewPayload.review_id,review,save_mode:saveMode});
    }catch(error){
      showSaveReceipt(null,error.message||'保存失败，原文件保持不变。');
      if(button){button.disabled=false;button.textContent='确认并保存'}
      if(error.status===409){showToast('该日期已有记录，请重新选择保存方式。');openSaveModeDialog()}
      return;
    }
    if(result.status!=='NO_CHANGES'){state.reviewPayload=null;state.draftRaw='';state.reviewSource=''}
    if(result.status!=='NO_CHANGES'&&(result.training_updated||Number(result.saved_movements||0)>0)){
      try{invalidateMovementUsage()}catch(error){console.warn('[Daily Entry] save committed; movement cache refresh failed',error)}
    }
    if(result.status!=='NO_CHANGES'){void autoSyncAfterSave().then(outcome=>{if(outcome){showToast(autoSyncOutcomeMessage(outcome));showAutoSyncReceipt(outcome)}}).catch(error=>console.warn('[Daily Entry] auto-sync deferred',error))}
    const refreshPromise=refreshWebState().catch(error=>{console.warn('[Daily Entry] save committed; archive refresh failed',error);showToast('记录已保存，但页面状态刷新失败，请稍后查看。');return null});
    try{navigate('quick')}catch(error){console.warn('[Daily Entry] save committed; route refresh failed',error)}
    try{showSaveReceipt(result)}catch(error){console.warn('[Daily Entry] save receipt failed',error)}
    void refreshPromise.then(()=>{if(state.view==='quick'&&!state.saving)quickPage()});
    try{
      if(result.status!=='NO_CHANGES'&&result.training_updated)emitGuardianIntent('training-save',buildTrainingSaveSummary(result),{id:`training-save:${result.record_id||result.date}`});
      emitGuardianWeightMilestone();
    }catch(error){console.warn('[Daily Entry] save presentation skipped',error)}
  }finally{state.saving=false}
}
function reviewDuplicateCount(){const duplicates=state.reviewPayload?.duplicates||{};return Object.values(duplicates).reduce((sum,value)=>sum+Number(value||0),0)}
function openSaveModeDialog(){document.querySelector('#save-mode-dialog')?.remove();document.body.insertAdjacentHTML('beforeend',`<dialog id="save-mode-dialog" class="save-mode-dialog" aria-labelledby="save-mode-title" aria-describedby="save-mode-copy"><form method="dialog" class="save-mode-sheet"><header><span class="eyebrow">SAVE DECISION / 同日记录</span><button class="save-mode-close" value="cancel" aria-label="关闭保存方式选择">×</button></header><div class="save-mode-heading"><span aria-hidden="true">!</span><div><h2 id="save-mode-title">该日期已有记录</h2><p id="save-mode-copy">请选择本次内容的保存方式。原记录会在你确认之前保持不变。</p></div></div><div class="save-mode-options"><button type="button" class="save-mode-option is-selective" data-save-mode-choice="append_training"><span><small>推荐</small><strong>选择性保存</strong></span><p>保留现有 Body 与 Diet，仅将本次训练作为同日另一条训练记录追加。</p><b aria-hidden="true">→</b></button><button type="button" class="save-mode-option is-overwrite" data-save-mode-choice="overwrite"><span><small>完整替换</small><strong>覆盖保存</strong></span><p>使用当前 Review 内容覆盖该日期已有的 Body、Diet 与 Training。</p><b aria-hidden="true">→</b></button></div><footer><button class="btn btn-light" value="cancel">取消 / 返回 Review</button><small>选择后才会执行保存；写入前仍沿用现有备份机制。</small></footer></form></dialog>`);const dialog=$('#save-mode-dialog');localizeKnownUiCopy(dialog,uiLanguage());if(uiLanguage()==='en')localizeEnglishSurface(dialog);dialog.addEventListener('click',event=>{const option=event.target.closest('[data-save-mode-choice]');if(!option)return;const mode=option.dataset.saveModeChoice;dialog.close();saveWebReview(mode)});dialog.addEventListener('close',()=>dialog.remove(),{once:true});dialog.showModal();requestAnimationFrame(()=>dialog.querySelector('.is-selective')?.focus())}
