  back:{id:'back',labelCn:'背',labelEn:'BACK',displayTitle:'Back Training Records',subtitle:'宽度、深度与稳定控制：整理下拉、划船和拉背训练。',accent:'#34776f',accentSoft:'#afd6cc',accentDeep:'#16463f',glow:'rgba(52,119,111,.2)',backgroundGradient:'radial-gradient(circle at 18% 10%,rgba(52,119,111,.21),transparent 36%)',motif:'body-themes-v2/back.png',personality:'structured',keywords:['背','背部','引体','下拉','划船','高拉','拉背','back','row','pulldown','pull-up'],emptyStateTitle:'背部训练档案为空',emptyStateDescription:'引体、下拉或划船记录会在保存后自动归入这个主题。'},
