function analysisExportRoot(){return $('.analysis-export-page')}
function analysisExportPrimaryButton(){return $('#analysis-export-primary-action')}
function analysisExportActiveInput(){const root=analysisExportRoot();return root?.dataset.inputMode==='json'?$('#analysis-export-request'):$('#analysis-export-natural-language')}
function analysisExportSetPrimaryLabel(label,disabled=false){const button=analysisExportPrimaryButton();if(!button)return;button.innerHTML=`${esc(label)} <span>→</span>`;button.disabled=disabled}
function analysisExportTransitionText(number,label,caption){const copy=$('#analysis-export-orb-copy'),captionNode=$('#analysis-export-stage-caption');if(!copy||!captionNode)return;const reduced=window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;if(reduced){$('#analysis-export-orb-number').textContent=number;$('#analysis-export-orb-label').textContent=label;captionNode.textContent=caption;return}copy.classList.add('is-out');captionNode.classList.add('is-out');clearTimeout(analysisExportTransitionText.timer);analysisExportTransitionText.timer=setTimeout(()=>{const numberNode=$('#analysis-export-orb-number'),labelNode=$('#analysis-export-orb-label');if(numberNode)numberNode.textContent=number;if(labelNode)labelNode.textContent=label;captionNode.textContent=caption;copy.classList.remove('is-out');captionNode.classList.remove('is-out')},220)}
function analysisExportSetProgress(degrees){$('#analysis-export-stage-orb')?.style.setProperty('--orb-progress',`${degrees}deg`)}
function analysisExportInputProgress(){const value=analysisExportActiveInput()?.value.trim()||'';return Math.min(118,Math.max(0,value.length*2.6))}
function analysisExportSetScopeReady(ready){const root=analysisExportRoot();if(root)root.dataset.scopeReady=ready?'true':'false'}
function setAnalysisExportProtocolMode(mode='guided'){
  const root=analysisExportRoot();if(!root)return;const active=mode==='json'?'json':'guided';root.dataset.inputMode=active;
  $$('[data-analysis-export-mode]',root).forEach(button=>{const selected=button.dataset.analysisExportMode===active;button.classList.toggle('is-active',selected);button.setAttribute('aria-selected',String(selected))});
  const panels=[['guided','#analysis-export-natural-pane'],['json','#analysis-export-json-pane']];panels.forEach(([panelMode,selector])=>{const panel=$(selector);if(!panel)return;const selected=panelMode===active;panel.hidden=!selected;panel.classList.toggle('is-active',selected)});
  const natural=active==='guided';const note=$('#analysis-export-local-note');if(note)note.textContent=natural?'只在本地解释，不上传':'本地校验 JSON，不上传';analysisExportSetPrimaryLabel(natural?'解释需求':'验证 JSON');analysisExportResetEvidence();
}
function protocolRequestValue(){try{return JSON.parse($('#analysis-export-request')?.value||'')}catch(error){throw new Error(`JSON 无法解析：${error.message}`)}}
function setAnalysisExportProtocolStage(stage='request'){
  const root=analysisExportRoot();if(!root)return;const mode=root.dataset.inputMode==='json'?'json':'guided',previousStage=state.analysisExportStage;state.analysisExportStage=stage;root.dataset.stage=stage;
  const orb=$('#analysis-export-stage-orb'),stateNode=$('#analysis-export-evidence-state'),next=$('#analysis-export-next'),back=$('#analysis-export-back'),result=$('#analysis-export-natural-result'),preview=$('#analysis-export-protocol-result');
  orb?.classList.remove('is-processing','is-sealed','is-done','is-error');
  const labels={request:['01','描述需求','输入问题后，系统会先解释，再提出数据范围。','第 1 步'],validate:['01',mode==='json'?'正在验证':'正在解释','正在处理，请稍候。','处理中'],scope:['02','确认范围','检查建议的数据包，再进入预览。','第 2 步'],preview:['03','预览导出','确认最终范围后，生成只读数据包。','第 3 步'],done:['✓','已就绪','只读数据包已准备完成。','已就绪'],error:['!','需要修改','请按提示调整输入后重试。','需要修改']};
  const info=labels[stage]||labels.request;analysisExportTransitionText(...info.slice(0,3));if(stateNode){stateNode.textContent=info[3];stateNode.dataset.status=stage}
  if(stage==='request'){orb?.classList.add('is-request');orb?.style.setProperty('--orb-accent','var(--analysis-brass)');analysisExportSetProgress(analysisExportInputProgress());result&&(result.hidden=true);preview&&(preview.hidden=true);analysisExportSetScopeReady(false);if(back)back.disabled=true;if(next)next.disabled=true;}
  if(stage==='validate'){orb?.classList.add('is-processing');orb?.style.setProperty('--orb-accent','var(--analysis-brass)');analysisExportSetProgress(165);result&&(result.hidden=true);preview&&(preview.hidden=true);if(back)back.disabled=true;if(next)next.disabled=true;}
  if(stage==='scope'){orb?.classList.add('is-sealed');orb?.style.setProperty('--orb-accent','var(--analysis-mint-deep)');analysisExportSetProgress(238);result&&(result.hidden=false);preview&&(preview.hidden=true);if(back)back.disabled=false;if(next){next.disabled=root.dataset.scopeReady!=='true';next.textContent=mode==='json'?'查看预览':'进入预览';}}
  if(stage==='preview'){orb?.classList.add('is-sealed');orb?.style.setProperty('--orb-accent','var(--analysis-brass)');analysisExportSetProgress(322);result&&(result.hidden=true);preview&&(preview.hidden=false);if(back)back.disabled=false;if(next){next.disabled=false;next.textContent='确认并下载';}}
  if(stage==='done'){orb?.classList.add('is-done');orb?.style.setProperty('--orb-accent','var(--analysis-mint-deep)');analysisExportSetProgress(360);result&&(result.hidden=true);preview&&(preview.hidden=false);if(back)back.disabled=false;if(next){next.disabled=true;next.textContent='已生成';}}
  if(stage==='error'){orb?.classList.add('is-error');orb?.style.setProperty('--orb-accent','var(--analysis-error)');analysisExportSetProgress(160);result&&(result.hidden=false);preview&&(preview.hidden=true);if(back)back.disabled=false;if(next)next.disabled=true;}
  if(stage==='validate')emitGuardianIntent('analysis-loading',{stage:mode==='json'?'Validating structured request':'Interpreting structured scope'},{id:'analysis-active'});
  else if(['scope','preview','done','error','request'].includes(stage))finishGuardianIntent('analysis-active',stage);
  if(stage==='preview'&&previousStage!=='preview'){const source=state.formalSemanticPreview||{},requests=source.requests||source.request||state.analysisExportProtocolRequest||[],previews=state.formalSemanticPreviews?.length?state.formalSemanticPreviews:[state.analysisExportProtocolPreview].filter(Boolean);emitGuardianIntent('analysis-result',buildStructuredAnalysisSummary(requests,previews),{id:`analysis-result:${source.preview_context_id||Date.now()}`})}
}
function analysisExportResetEvidence(){const root=analysisExportRoot();if(!root)return;state.analysisExportProtocolPreview=null;state.analysisExportProtocolRequest=null;state.formalSemanticPreview=null;state.formalSemanticPreviews=[];state.formalSemanticPreviewContextId='';analysisExportSetScopeReady(false);const result=$('#analysis-export-natural-result'),preview=$('#analysis-export-protocol-result'),digest=$('#analysis-export-scope-digest'),bundles=$('#analysis-export-bundle-list');if(digest)digest.innerHTML='';if(bundles)bundles.innerHTML='';if(result)result.hidden=true;if(preview){preview.hidden=true;preview.innerHTML=''}setAnalysisExportProtocolStage('request')}
function bindAnalysisExportMotion(){const desk=$('#analysis-export-desk'),primary=analysisExportPrimaryButton();if(desk)desk.addEventListener('pointermove',event=>{if(window.matchMedia?.('(prefers-reduced-motion: reduce)').matches)return;const rect=desk.getBoundingClientRect();desk.style.setProperty('--spot-x',`${event.clientX-rect.left}px`);desk.style.setProperty('--spot-y',`${event.clientY-rect.top}px`)});if(primary){primary.addEventListener('pointermove',event=>{if(window.matchMedia?.('(prefers-reduced-motion: reduce)').matches)return;const rect=primary.getBoundingClientRect();primary.style.setProperty('--mx',`${((event.clientX-rect.left)/rect.width-.5)*4}px`);primary.style.setProperty('--my',`${((event.clientY-rect.top)/rect.height-.5)*3}px`)});primary.addEventListener('pointerleave',()=>{primary.style.setProperty('--mx','0px');primary.style.setProperty('--my','0px')})}}
function protocolTimeRangeSummary(datasets){const ranges=(datasets||[]).map(item=>{const range=item?.time_range||{};if(range.mode==='recent_days')return `最近 ${range.days||'几'} 天`;if(range.start||range.end)return `${range.start||'起始日期'} 至 ${range.end||'结束日期'}`;if(range.mode==='all_available')return '全部可用记录';return range.mode||'指定范围'});return [...new Set(ranges)].join(' / ')||'指定范围'}
function renderAnalysisExportScopeDigest(payload={}){const target=$('#analysis-export-scope-digest');if(!target)return;const preview=payload.preview||payload, datasets=Array.isArray(preview.datasets)?preview.datasets:[],records=Number.isFinite(Number(preview.record_count))?`${Number(preview.record_count)} 条记录`:'记录数待预览';target.innerHTML=`<div><strong>${datasets.length||0}</strong><span>个数据集</span></div><div><strong>${esc(protocolTimeRangeSummary(datasets))}</strong><span>${esc(records)}</span></div>`}
function naturalStatusLabel(status=''){return ({ready:'范围已准备',candidate_confirmation_required:'请选择正式动作',needs_clarification:'请补充范围',planner_required:'需要分析规划',rejected_contract:'请修改请求',NO_EXPORT_REQUIRED:'没有识别到导出范围',unsupported:'暂不支持该范围',error:'导出出错',needs_confirmation:'请重新确认范围'})[status]||'需要修改'}
function naturalStatusMessage(status=''){return ({planner_required:'这句话需要比较或判断关系；请改成明确的数据导出范围。',rejected_contract:'请求触发只读安全边界；不允许 Raw、写入或删除正式数据。',unsupported:'请将需求改成明确的数据范围。',NO_EXPORT_REQUIRED:'请补充数据域和时间范围。',needs_clarification:'动作名称存在歧义，请从正式动作候选中选择。'})[status]||'请补充或修改导出范围后重试。'}
function naturalTypeLabel(type=''){return ({body:'体重与身体',diet:'饮食与宏量',training:'训练记录',movement:'动作记录',movement_progress:'动作进步',quality:'数据质量'})[type]||type||'数据'}
function protocolNaturalRangeLabel(item={}){const range=item?.time_range||{};if(range.mode==='recent_days')return `最近 ${range.days||'几'} 天`;if(range.start||range.end)return `${range.start||'起始日期'} 至 ${range.end||'结束日期'}`;if(range.mode==='all_available')return '全部可用记录';return range.mode||'指定范围'}
function analysisExportScopeMarkup(requests=[],previews=[]){const list=(Array.isArray(requests)?requests:[requests]).filter(Boolean);return list.map((request,index)=>{const datasets=Array.isArray(request.datasets)?request.datasets:[],preview=previews[index]?.preview||{};const count=Number.isFinite(Number(preview.record_count))?`${Number(preview.record_count)} 条记录`:'';return `<article class="analysis-export-bundle"><div class="analysis-export-bundle-head"><strong>${list.length>1?`第 ${index+1} 组`:'导出范围'}</strong><span>${datasets.length} 个数据集${count?` ? ${count}`:''}</span></div><div class="analysis-export-bundle-datasets">${datasets.map(item=>`<span><b>${esc(naturalTypeLabel(item.type))}</b><small>${esc(protocolNaturalRangeLabel(item))}</small></span>`).join('')||'<span>尚未识别数据</span>'}</div></article>`}).join('')||'<p class="analysis-export-empty">尚未形成导出范围。</p>'}
