function renderAnalysisExportScope(requests=[],previews=[],title='已识别的范围'){const result=$('#analysis-export-natural-result'),digest=$('#analysis-export-scope-digest'),bundles=$('#analysis-export-bundle-list');if(!result||!digest||!bundles)return;const datasets=(requests||[]).flatMap(item=>Array.isArray(item?.datasets)?item.datasets:[]),records=(previews||[]).reduce((total,item)=>total+(Number(item?.preview?.record_count)||0),0);renderAnalysisExportScopeDigest({datasets,record_count:records||undefined});bundles.innerHTML=`<h4>${esc(title)}</h4>${analysisExportScopeMarkup(requests,previews)}`;result.hidden=false;analysisExportSetScopeReady(true);setAnalysisExportProtocolStage('scope')}
