function renderAnalysisExportError(title,message,details=[]){const result=$('#analysis-export-natural-result');if(!result)return;const lines=(details||[]).map(item=>typeof item==='string'?item:(item?.message||item?.code||'')).filter(Boolean);result.innerHTML=`<div class="analysis-export-error-copy"><h4>${esc(title)}</h4><p>${esc(message||'请调整输入后重试。')}</p>${lines.length?`<ul>${lines.map(item=>`<li>${esc(item)}</li>`).join('')}</ul>`:''}</div>`;result.hidden=false;setAnalysisExportProtocolStage('error')}
function renderFormalSemanticPreview(payload={}){const status=payload.status||'error',requests=Array.isArray(payload.requests)&&payload.requests.length?payload.requests:(payload.request?[payload.request]:[]),errors=Array.isArray(payload.errors)?payload.errors:[],confirmations=Array.isArray(payload.confirmations)?payload.confirmations:[],candidates=Array.isArray(payload.candidates)?payload.candidates:[];state.formalSemanticPreview=status==='ready'?payload:null;if(status==='ready'){renderAnalysisExportScope(requests,state.formalSemanticPreviews||[],'已识别的导出范围');return}if(candidates.length){renderNaturalCandidateState(payload);return}renderAnalysisExportError(naturalStatusLabel(status),[...confirmations,...errors.map(item=>typeof item==='string'?item:(item?.message||item?.code||'')),naturalStatusMessage(status)].filter(Boolean).join(' ? '));}
function previewDatasetMarkup(preview,index){const datasets=Array.isArray(preview.datasets)?preview.datasets:[],resolution=Array.isArray(preview.movement_body_part_resolution)?preview.movement_body_part_resolution:[],selector=resolution.map(item=>item?.movement_name||item?.movement_id||item?.body_part||item?.selector?.value).filter(Boolean);return `<article class="analysis-export-preview-sheet"><h4>${datasets.length>1?`第 ${index+1} 组 ? `:''}预览导出</h4><div class="analysis-export-preview-row"><span>日期范围</span><strong>${esc(protocolTimeRangeSummary(datasets))}</strong></div><div class="analysis-export-preview-row"><span>数据集</span><strong>${datasets.length} 个</strong></div>${datasets.map(item=>`<div class="analysis-export-preview-dataset"><b>${esc(naturalTypeLabel(item.type))}</b><span>${esc(protocolNaturalRangeLabel(item))}</span><small>fields: ${esc((item.fields||[]).join('?')||'协议默认字段')}</small></div>`).join('')}<div class="analysis-export-preview-row"><span>动作筛选</span><strong>${esc(selector.join('?')||'未指定动作')}</strong></div><div class="analysis-export-preview-row"><span>只读边界</span><strong>本地，不上传，不写入</strong></div>${(preview.warnings||[]).length?`<p class="analysis-export-validator-warning">${esc(preview.warnings.join(' ? '))}</p>`:''}</article>`}
function renderAnalysisExportPreview(previews=[],requests=[],plan={}){const target=$('#analysis-export-protocol-result');if(!target)return;const items=(Array.isArray(previews)?previews:[previews]).filter(Boolean);if(!items.length){renderAnalysisExportError('预览不可用','没有可以确认的数据范围。');return}target.innerHTML=`<div class="analysis-export-preview-heading"><h4>最终预览</h4><p>以下内容来自真实 Preview。</p></div>${naturalPlanMarkup(plan)}${items.map((item,index)=>previewDatasetMarkup(item.preview||{},index)).join('')}<div class="analysis-export-confirmation"><label><input id="analysis-export-confirm" type="checkbox"> 我确认当前范围</label><button class="analysis-export-primary" type="button" data-analysis-export-confirm disabled>确认并下载 <span>→</span></button><div class="analysis-export-downloads" id="analysis-export-downloads"></div></div>`;target.hidden=false;setAnalysisExportProtocolStage('preview')}
