function bodyWeightMicroBars(){
  const records=state.body
    .map(record=>({record,index:state.body.indexOf(record),date:dateOf(record),weight:Number(value(record,'Weight (kg)'))}))
    .filter(item=>item.date&&Number.isFinite(item.weight))
    .slice(0,180)
    .reverse();
  if(records.length<2)return '';
  const weights=records.map(item=>item.weight),minimum=Math.min(...weights),maximum=Math.max(...weights);
  let axisMinimum=Math.max(0,Math.floor(minimum-3)),axisMaximum=Math.ceil(maximum+2);
  const minimumRange=7,missingRange=Math.max(0,minimumRange-(axisMaximum-axisMinimum));
  axisMinimum=Math.max(0,axisMinimum-Math.ceil(missingRange*.6));
  axisMaximum+=Math.floor(missingRange*.4);
  const range=Math.max(axisMaximum-axisMinimum,.5);
  const bars=records.map((item,index)=>{
    const previous=records[index-1],direction=!previous?'is-neutral':item.weight<previous.weight?'is-down':item.weight>previous.weight?'is-up':'is-neutral';
    const height=18+((item.weight-axisMinimum)/range)*74;
    return `<button type="button" class="weight-micro-bar ${direction}" style="--bar-height:${height.toFixed(2)}%;--interaction-index:${index}" data-detail="body" data-index="${item.index}" data-weight-tip="${esc(item.date)} · ${item.weight.toFixed(1)} kg" aria-label="打开 ${esc(item.date)} 身体记录，体重 ${item.weight.toFixed(1)} kg"><span></span></button>`;
  }).join('');
  const dateIndexes=[0,Math.round((records.length-1)/3),Math.round((records.length-1)*2/3),records.length-1];
  return `<section class="body-weight-rhythm" aria-label="最近 ${records.length} 天体重变化"><header><span class="eyebrow">WEIGHT / RECENT ${records.length}</span><button class="weight-average-trigger" data-open-weight-average title="比较两个日期前 7 日的平均体重">7D AVG</button><strong>${records.at(-1).weight.toFixed(1)}<small>kg</small></strong></header><div class="weight-micro-plot"><div class="weight-y-axis" aria-hidden="true"><span>${axisMaximum.toFixed(1)}</span><span>${(axisMinimum+range/2).toFixed(1)}</span><span>${axisMinimum.toFixed(1)}</span><small>kg</small></div><div class="weight-micro-scroll" tabindex="0" aria-label="体重图表，可横向滚动查看更多日期"><div class="weight-micro-track" style="--bar-count:${records.length};--track-width:${records.length*11}px"><div class="weight-micro-array">${bars}</div><div class="weight-micro-dates">${dateIndexes.map(index=>`<span>${esc(records[index].date.slice(5))}</span>`).join('')}</div></div></div></div></section>`;
}

function sevenDayWeightAverage(records,endDate){const end=new Date(`${endDate}T00:00:00`);if(Number.isNaN(end.getTime()))return null;const start=new Date(end);start.setDate(end.getDate()-6);const startDate=[start.getFullYear(),String(start.getMonth()+1).padStart(2,'0'),String(start.getDate()).padStart(2,'0')].join('-');const values=records.filter(item=>item.date>=startDate&&item.date<=endDate).map(item=>item.weight);return values.length?{average:values.reduce((sum,item)=>sum+item,0)/values.length,count:values.length}:null}
function weightAverageCompare(records){const english=uiLanguage()==='en',latest=records.at(-1)?.date||'',first=records[0]?.date||latest;return `<dialog id="weight-average-dialog" class="weight-average-dialog" aria-labelledby="weight-average-title"><form method="dialog"><header class="weight-average-head"><span class="eyebrow">WEIGHT / 7-DAY AVG</span><button class="weight-average-close" type="submit" aria-label="${english?'Close':'关闭'}">×</button></header><h2 id="weight-average-title">${english?'Seven-day average comparison':'七日体重均值对比'}</h2><p class="weight-average-sub">${english?'Compare the average for each selected date and its previous six days.':'各取所选日期及其前 6 天，比较两端 7 日均值的差值。'}</p><div class="weight-average-panel"><label>${english?'Date A':'日期 A'}<input type="date" data-weight-average-date="a" value="${esc(first)}"></label><label>${english?'Date B':'日期 B'}<input type="date" data-weight-average-date="b" value="${esc(latest)}"></label><output id="weight-average-result" class="weight-average-result">${weightAverageCompareResult(records,first,latest)}</output></div></form></dialog>`}
function weightAverageCompareResult(records,dateA,dateB){const english=uiLanguage()==='en',a=sevenDayWeightAverage(records,dateA),b=sevenDayWeightAverage(records,dateB);if(!a||!b)return english?'Not enough weight entries in one or both seven-day windows.':'所选日期的 7 日窗口没有足够体重记录。';const delta=b.average-a.average,sign=delta>0?'+':'';return english?`A ${a.average.toFixed(2)} kg (${a.count} entries) · B ${b.average.toFixed(2)} kg (${b.count} entries) · Change ${sign}${delta.toFixed(2)} kg`:`A ${a.average.toFixed(2)} kg（${a.count} 条） · B ${b.average.toFixed(2)} kg（${b.count} 条） · 差值 ${sign}${delta.toFixed(2)} kg`}
document.addEventListener('click',event=>{if(!event.target.closest('[data-open-weight-average]'))return;const rows=state.body.map(record=>({date:dateOf(record),weight:Number(value(record,'Weight (kg)'))})).filter(item=>item.date&&Number.isFinite(item.weight)).sort((a,b)=>a.date.localeCompare(b.date));document.querySelector('#weight-average-dialog')?.remove();document.body.insertAdjacentHTML('beforeend',weightAverageCompare(rows));document.querySelector('#weight-average-dialog')?.showModal()},true);
document.addEventListener('change',event=>{if(!event.target.matches('[data-weight-average-date]'))return;const records=state.body.map(record=>({date:dateOf(record),weight:Number(value(record,'Weight (kg)'))})).filter(item=>item.date&&Number.isFinite(item.weight)).sort((a,b)=>a.date.localeCompare(b.date));const result=$('#weight-average-result'),a=$('[data-weight-average-date="a"]')?.value,b=$('[data-weight-average-date="b"]')?.value;if(result)result.textContent=weightAverageCompareResult(records,a,b)},true);

function enhanceOfficialBodyRecords(){
  const rows=$('#body-rows');
  if(rows&&!$('.body-weight-rhythm')){
    const slot=$('#body-weight-slot');
    if(slot)slot.innerHTML=bodyWeightMicroBars();
    else rows.insertAdjacentHTML('beforebegin',bodyWeightMicroBars());
    const section=$('.body-weight-rhythm'),tooltip=document.createElement('div');
    tooltip.className='body-weight-tooltip';
    tooltip.hidden=true;
    section?.appendChild(tooltip);
    if(section)$$('.weight-micro-bar',section).forEach(bar=>{
      const show=()=>{
        if(!section||!tooltip)return;
        tooltip.textContent=bar.dataset.weightTip||'';
        const barRect=bar.getBoundingClientRect(),sectionRect=section.getBoundingClientRect(),plotRect=$('.weight-micro-plot',section).getBoundingClientRect();
        tooltip.style.top=`${plotRect.top-sectionRect.top+5}px`;
        tooltip.hidden=false;
        const half=tooltip.offsetWidth/2,desired=barRect.left+barRect.width/2-sectionRect.left;
        tooltip.style.left=`${Math.max(half+8,Math.min(sectionRect.width-half-8,desired))}px`;
      };
      const hide=()=>{tooltip.hidden=true};
      bar.addEventListener('mouseenter',show);
      bar.addEventListener('mouseleave',hide);
      bar.addEventListener('focus',show);
      bar.addEventListener('blur',hide);
    });
    const viewport=$('.weight-micro-scroll');
    requestAnimationFrame(()=>{if(viewport)viewport.scrollLeft=viewport.scrollWidth});
  }
  $$('.body-slip').forEach((record,index)=>{
    record.classList.add('has-record-interaction');
    record.setAttribute('role','button');
    record.setAttribute('tabindex','0');
    record.style.setProperty('--interaction-index',index);
    record.setAttribute('aria-label',`打开 ${record.querySelector('.body-slip-date strong')?.textContent||''} 身体记录`);
  });
}
const renderBodyRowsWithOfficialInteractions=renderBodyRows;
renderBodyRows=function(...args){renderBodyRowsWithOfficialInteractions(...args);enhanceOfficialBodyRecords()};

function enhanceOfficialMovementChart(movementId){
  const chart=$('.movement-progress-panel .progress-chart');
  if(!chart)return;
  const history=Array.isArray(state.movementHistory?.progress_history)?state.movementHistory.progress_history:[];
  const available=history.map(record=>({...record,...movementRecordMetrics(record)})).filter(record=>!record.superset&&record.structured&&(record.volume>0||(record.maxLoad===0&&record.totalReps>0))).slice(0,8).reverse();
  if(!available.length)return;
  const useLoad=chart.dataset.chartMetric==='load';
  const records=available.filter(record=>useLoad?record.maxLoad>0:record.maxLoad===0);
  const bars=$$('.volume-bars rect',chart),dots=$$('.load-dots circle',chart);
  const panel=chart.closest('.movement-progress-panel'),tooltip=document.createElement('div');
  tooltip.className='movement-chart-tooltip';
  tooltip.hidden=true;
  panel?.appendChild(tooltip);
  const hitLayer=document.createElementNS('http://www.w3.org/2000/svg','g');
  hitLayer.setAttribute('class','chart-hit-zones');
  records.forEach((record,index)=>{
    [bars[index],dots[index]].filter(Boolean).forEach(mark=>{
      mark.classList.add('has-chart-interaction');
      mark.dataset.trainingDate=String(record.date||'').slice(0,10);
      mark.dataset.trainingMovementId=String(movementId||'');
      mark.setAttribute('role','button');
      mark.setAttribute('tabindex','0');
      mark.setAttribute('aria-label',`${uiLanguage()==='en'?'Open':'打开'} ${record.date||''} ${uiLanguage()==='en'?'training record':'训练记录'}`);
      mark.style.setProperty('--interaction-index',index);
      mark.dataset.chartIndex=String(index);
    });
    const dot=dots[index],bar=bars[index],sets=(record.sets_lines||[]).filter(Boolean),english=uiLanguage()==='en',lineValue=useLoad?(english?`Max weight ${record.maxLoad} kg`:`最大重量 ${record.maxLoad} kg`):(english?`${record.totalReps} reps`:`总次数 ${record.totalReps} 次`),capacityValue=english?`Volume ${record.volume} kg·reps`:`容量 ${record.volume} kg·次`,tip=`${record.date} · ${lineValue} · ${capacityValue}${sets.length?` · ${sets.join(' / ')}`:''}`;
    const targets=[];
    if(dot){
      const circle=document.createElementNS('http://www.w3.org/2000/svg','circle');
      circle.setAttribute('cx',dot.getAttribute('cx'));
      circle.setAttribute('cy',dot.getAttribute('cy'));
      circle.setAttribute('r','13');
      targets.push(circle);
    }
    if(bar){
      const rect=document.createElementNS('http://www.w3.org/2000/svg','rect'),x=Number(bar.getAttribute('x')),y=Number(bar.getAttribute('y')),width=Number(bar.getAttribute('width')),height=Number(bar.getAttribute('height'));
      rect.setAttribute('x',String(x-3));
      rect.setAttribute('y',String(y-3));
      rect.setAttribute('width',String(width+6));
      rect.setAttribute('height',String(Math.max(12,height+6)));
      rect.setAttribute('rx','5');
      targets.push(rect);
    }
    const show=target=>{
      [bars[index],dots[index]].filter(Boolean).forEach(mark=>mark.classList.add('is-hovered'));
      if(!tooltip||!panel)return;
      tooltip.textContent=tip;
      tooltip.hidden=false;
      const targetRect=target.getBoundingClientRect(),panelRect=panel.getBoundingClientRect();
      const tooltipWidth=tooltip.offsetWidth,tooltipHeight=tooltip.offsetHeight,gutter=12;
      const desiredLeft=targetRect.left+targetRect.width/2-panelRect.left-tooltipWidth/2;
      const maxLeft=Math.max(gutter,panelRect.width-tooltipWidth-gutter);
      tooltip.style.left=`${Math.max(gutter,Math.min(maxLeft,desiredLeft))}px`;
      const targetTop=targetRect.top-panelRect.top,targetBottom=targetRect.bottom-panelRect.top;
      const above=targetTop-tooltipHeight-10,below=targetBottom+10;
      const desiredTop=above>=gutter?above:below;
      tooltip.style.top=`${Math.max(gutter,Math.min(panelRect.height-tooltipHeight-gutter,desiredTop))}px`;
    };
    const hide=()=>{
      [bars[index],dots[index]].filter(Boolean).forEach(mark=>mark.classList.remove('is-hovered'));
      if(tooltip)tooltip.hidden=true;
    };
    targets.forEach((target,targetIndex)=>{
      target.setAttribute('class','chart-hit-zone has-chart-interaction');
      target.dataset.trainingDate=String(record.date||'').slice(0,10);
      target.dataset.trainingMovementId=String(movementId||'');
      target.dataset.chartIndex=String(index);
      target.dataset.chartValue=String(useLoad?record.maxLoad:record.totalReps);
      target.dataset.chartCapacity=String(record.volume);
      target.dataset.chartTip=tip;
      target.setAttribute('role','button');
      target.setAttribute('tabindex',targetIndex===0?'0':'-1');
      target.setAttribute('aria-label',`${tip}${english?', open training record':'，点击打开训练记录'}`);
      const showTarget=()=>show(target);
      target.addEventListener('mouseenter',showTarget);
      target.addEventListener('mouseleave',hide);
      target.addEventListener('focus',showTarget);
      target.addEventListener('blur',hide);
      hitLayer.appendChild(target);
    });
  });
  chart.appendChild(hitLayer);
  chart.classList.add('has-chart-interactions');
  chart.querySelector('.load-line')?.classList.add('has-entry-animation');
}
