// Keep Cloud Sync focused on the user's decision: are the three surfaces in
// agreement, and should I sync now? Technical evidence remains available on
// demand so the default screen stays readable for everyday use.
cloudSyncPage=async function(){
  main.innerHTML='<div class="loading-page"><i></i><p>正在读取同步状态…</p></div>';
  try{state.cloudSync=await api('/api/cloud-sync/status')}catch(error){state.cloudSync={error:error.message}}
  state.syncStatus=state.cloudSync;
  updateSyncNav();
  const status=state.cloudSync||{},presentation=cloudStatusPresentation(status),isVerified=['SYNCED','NO_CHANGES'].includes(presentation.code);
  const localDate=status.local_latest_record_date||'暂无记录',cloudDate=status.cloud_latest_record_date||'尚未确认';
  const localState=localDate==='暂无记录'?'暂无记录':status.payload_stale||['LOCAL_NEWER','LOCAL_CHANGES','READY'].includes(presentation.code)?'有新记录待同步':'已保存';
  const cloudState=isVerified?'已确认':cloudDate==='尚未确认'?'待同步':'待确认';
  const phoneState=isVerified&&cloudDate!=='尚未确认'?'可查看':'待确认';
  const phoneNote=isVerified&&cloudDate!=='尚未确认'?'手机端读取同一份云端副本':'完成同步后再到手机端查看';
  const real=Boolean(status.network_upload_configured),ready=Boolean(status.upload_provider_ready);
  const runLabel=real?'立即同步':ready?'执行本地检查':'查看同步说明';
  const lastSync=status.last_sync_at||status.last_sync_result?.finished_at||'尚未同步';
  const advancedStatus=status.error?'当前无法读取同步状态，请稍后重试。':`上次同步：${lastSync}`;
  const technicalChecks=status.last_sync_result?.cloud_verification?.checks||{};
  const verifiedCount=Object.values(technicalChecks).filter(Boolean).length;
  const advancedResult=isVerified?'本次同步已通过完整校验。':verifiedCount?`已完成 ${verifiedCount} 项检查，仍需确认最终结果。`:'尚未形成完整校验结果。';
  const card=(label,value,note,klass)=>`<article class="cloud-sync-user-card ${klass||''}"><span>${label}</span><strong>${esc(value)}</strong><small>${esc(note)}</small></article>`;
  main.innerHTML=`<section class="page admin-page admin-sync-page cloud-sync-page cloud-sync-business" data-cloud-state="${esc(presentation[2])}"><button class="admin-back-link" data-tools-panel="overview">← 返回工具</button><header class="admin-page-header cloud-sync-business-head"><div><div class="admin-breadcrumb"><span>TOOLS</span><i>/</i><strong>CLOUD SYNC</strong></div><h1>Cloud Sync</h1><p>查看本地记录与云端副本是否一致，并在需要时手动同步。</p></div><div class="admin-header-actions"><span class="admin-status-badge ${isVerified?'is-clear':presentation[2]==='failed'?'is-review':''}"><i></i>${esc(presentation[0])}</span></div></header><section class="cloud-sync-user-grid" aria-label="同步范围">${card('本地记录',localState,localDate,'is-local')}${card('云端副本',cloudState,cloudDate,'is-cloud')}${card('手机端读取',phoneState,phoneNote,'is-phone')}</section><div class="admin-sync-local-state ${localState==='有新记录待同步'?'is-pending':isVerified?'is-synced':''}" role="status"><i></i><strong>${esc(localState)}</strong><span>${esc(presentation[1])}</span></div><section class="cloud-sync-business-layout"><section class="admin-panel admin-sync-primary cloud-sync-business-primary"><header class="admin-panel-header"><div><span class="admin-kicker">SYNC STATUS</span><h2>${esc(presentation[0])}</h2><p id="cloud-sync-stage">${esc(cloudSyncModeHint(status))}</p></div><span class="admin-panel-meta">${esc(cloudSyncModeText(status))}</span></header><div class="cloud-sync-business-facts"><div><span>本地最新记录</span><strong>${esc(localDate)}</strong></div><div><span>云端最新记录</span><strong>${esc(cloudDate)}</strong></div><div><span>手机端读取</span><strong>${esc(phoneState)}</strong></div></div><div class="admin-sync-actions"><button class="admin-button admin-button-primary" data-cloud-sync-run>${esc(runLabel)} <span>→</span></button><button class="admin-button admin-button-quiet" data-cloud-sync-refresh>刷新状态</button></div><p class="admin-safety-note"><i></i>${real?'确认保存后会自动同步；手动同步用于立即检查最新结果。':ready?'当前为本地演练模式，不会更新真实云端。':'当前还未完成云端配置，本地记录不会受到影响。'}</p></section><aside class="admin-panel cloud-sync-business-help"><span class="admin-kicker">SYNC FEEDBACK</span><h2>${isVerified?'已经确认':'等待确认'}</h2><p>${esc(advancedStatus)}</p><p class="cloud-sync-feedback-note">${esc(advancedResult)}</p><button class="admin-button admin-button-outline admin-button-wide" data-tools-panel="health">查看数据问题 <span>→</span></button></aside></section><details class="admin-advanced cloud-sync-advanced"><summary><span><strong>高级信息</strong><small>仅在需要排查同步问题时查看</small></span><i>+</i></summary><div class="admin-advanced-body"><div class="admin-advanced-actions"><button class="link" data-cloud-sync-build>生成同步文件</button><button class="link" data-cloud-sync-directory>打开导入目录</button><button class="link" data-cloud-sync-preview ${status.manifest?.generated_at?'':'disabled'}>查看同步文件</button><button class="link" data-cloud-sync-copy>复制同步报告</button><button class="link" data-cloud-sync-guide>查看配置说明</button><button class="link" data-cloud-sync-env>复制环境信息</button><button class="link" data-cloud-sync-check="cloud">检查云端连接</button><button class="link" data-cloud-sync-check="ledger">检查手机端读取</button><button class="link" data-cloud-sync-check="allowlist">检查访问权限</button></div><details class="cloud-manual-verify"><summary>手动校验云端副本 <small>仅用于故障排查</small></summary><div><textarea id="cloud-meta-input" rows="5" placeholder='粘贴云端副本信息'></textarea><button class="btn" data-cloud-sync-verify>开始校验</button></div><div id="cloud-sync-verification" class="cloud-sync-verification"></div></details></div></details></section>`;
  loadArchiveHealth().then(()=>{const count=Number(state.archiveHealth?.issue_count||0),node=$('[data-sync-unresolved]'),badge=$('[data-sync-health-count]');if(node)node.textContent=String(count);if(badge)badge.textContent=count?`${count} 项待处理`:'当前无需处理'});
};

// Localize archive controls and labels without flattening the editorial
// English typography that carries the existing visual hierarchy.
const archiveNameZh=name=>({
  'Full Body':'全身','FULL BODY':'全身','Chest':'胸','CHEST':'胸','Back':'背','BACK':'背',
  'Legs':'腿','LEGS':'腿','Shoulders':'肩','SHOULDERS':'肩','Arms':'手臂','ARMS':'手臂'
}[String(name||'').trim()]||String(name||''));
function localizeBodyArchive(){
  if(uiLanguage()==='en'){localizeEnglishSurface(document.querySelector('main'));return}
  const page=document.querySelector('.body-archive');if(!page)return;
  const title=page.querySelector('.archive-heading .page-title');if(title&&title.textContent.trim()==='Body Records')title.insertAdjacentHTML('beforeend','<small class="archive-title-cn">身体记录</small>');
  const subtitle=page.querySelector('.archive-heading .page-subtitle');if(subtitle&&subtitle.textContent.includes('Daily measurements'))subtitle.textContent='按日期查看身体记录，备注保持清晰可读。';
  const search=page.querySelector('#body-search');if(search)search.placeholder='搜索备注或日期…';
  const time=page.querySelector('#body-time');time?.querySelectorAll('option').forEach(option=>{const map={'All time':'全部时间','Recent 7 days':'最近 7 天','Recent 14 days':'最近 14 天','Recent 30 days':'最近 30 天'};if(map[option.textContent.trim()])option.textContent=map[option.textContent.trim()]});
  const order=page.querySelector('#body-order');order?.querySelectorAll('option').forEach(option=>{const map={'Newest first':'最新记录在前','Oldest first':'最早记录在前'};if(map[option.textContent.trim()])option.textContent=map[option.textContent.trim()]});
  page.querySelectorAll('.body-slip-meta > span').forEach(node=>{const label=[...node.childNodes].find(item=>item.nodeType===Node.TEXT_NODE);if(label)label.textContent='训练 '});
  page.querySelectorAll('.body-slip-meta strong').forEach(node=>{node.textContent=archiveNameZh(node.textContent)});
  page.querySelectorAll('.record-open').forEach(node=>{if(node.textContent.trim().startsWith('Open record'))node.textContent='打开记录'});
  page.querySelectorAll('.records-status span').forEach(node=>{if(node.textContent.includes('Showing local records'))node.textContent='正在显示本地记录'});
}
function localizeTrainingArchive(){
  if(uiLanguage()==='en'){localizeEnglishSurface(document.querySelector('main'));return}
  const page=document.querySelector('.training-theme-page');if(!page)return;
  const title=page.querySelector('.training-theme-header h1');
  if(title&&!title.querySelector('.archive-title-cn')){const raw=title.textContent.trim(),name=raw.replace(/\s*Training Records$/,'').replace(/训练记录$/,'');const cn=!state.selectedBodyPart?'训练记录':name?`${archiveNameZh(name)}训练记录`:'训练记录';title.insertAdjacentHTML('beforeend',`<small class="archive-title-cn">${esc(cn)}</small>`)}
  const subtitle=page.querySelector('.training-theme-header .page-subtitle');if(subtitle)subtitle.textContent='完整保留动作与组数记录，可打开结构化详情编辑。';
  const deckTitle=page.querySelector('.body-theme-deck h2');if(deckTitle&&deckTitle.textContent.trim()==='Editable session archives.')deckTitle.textContent='训练主题档案。';
  const all=page.querySelector('.theme-overview');if(all){const label=[...all.childNodes].find(item=>item.nodeType===Node.TEXT_NODE);if(label)label.textContent='全部记录 '}
  page.querySelectorAll('.theme-cn').forEach(node=>{node.textContent=archiveNameZh(node.textContent)});
  page.querySelectorAll('.theme-meta').forEach(node=>{node.innerHTML=node.innerHTML.replace('sessions','次训练').replace('movements','个动作')});
  page.querySelectorAll('.theme-last').forEach(node=>{node.textContent=node.textContent.replace('Latest','最近一次').replace('Awaiting first record','尚无记录')});
  page.querySelectorAll('.training-theme-toolbar').forEach(toolbar=>{
    const search=toolbar.querySelector('#training-search');if(search)search.placeholder='搜索训练主题或日期…';
    toolbar.querySelectorAll('#training-order option').forEach(option=>{const map={'Newest first':'最新训练在前','Oldest first':'最早训练在前'};if(map[option.textContent.trim()])option.textContent=map[option.textContent.trim()]});
  });
  const index=page.querySelector('.training-index');
  if(index){const small=index.querySelector('h2 small');if(small)small.textContent=' 次训练记录';const copy=index.querySelector(':scope > p');if(copy)copy.textContent='按已保存的训练主题分组。';const note=index.querySelector('.training-index-note');if(note)note.textContent='选择一个训练主题';
    index.querySelectorAll('.training-focus-panel h2 small').forEach(node=>{node.textContent=' 次相关训练'});
    index.querySelectorAll('.focus-metrics small').forEach(node=>{const map={'LAST SESSION':'最近一次训练','MOVEMENTS':'动作数'};if(map[node.textContent.trim()])node.textContent=map[node.textContent.trim()]});
    index.querySelectorAll('.focus-movements > .eyebrow').forEach(node=>{if(node.textContent.trim()==='FREQUENT SIGNALS')node.textContent='常见动作'});
    index.querySelectorAll('.focus-open').forEach(node=>{const arrow=node.querySelector('span')?.outerHTML||' <span>→</span>';node.innerHTML=`查看最近详情${arrow}`});
  }
  page.querySelectorAll('.session-split').forEach(node=>{node.textContent=archiveNameZh(node.textContent)});
  page.querySelectorAll('.session-facts').forEach(node=>{const spans=node.querySelectorAll('span');if(spans[0])spans[0].textContent=spans[0].textContent.replace('movements','个动作');if(spans[1])spans[1].textContent='完整动作与组数记录'});
  page.querySelectorAll('.training-movement-copy small').forEach(node=>{if(node.textContent.trim()==='No structured sets')node.textContent='暂无结构化组数'});
  page.querySelectorAll('.record-open').forEach(node=>{if(node.textContent.trim().startsWith('Open structured detail'))node.textContent='查看结构化详情'});
  page.querySelectorAll('.records-status span').forEach(node=>{if(node.textContent.includes('Showing local records'))node.textContent='正在显示本地记录'});
}
